COLLDATA("tadabburar","ar",[[372,"§الشعراء\nwords\nالمَرجُومِينَالمَقتُولِينَ رَميًا بِالحِجَارَةِ.\nفَافتَحاحكُم.\nالمَشحُونِالمَملُوءِ بِالنَّاسِ، وَالدَّوَابِّ، وَالمَتَاعِ.\nرِيعٍمَكَانٍ مُرتَفِعٍ.\nآيَةًبِنَاءً عَالِيًا.\nتَعبَثُونَتُشرِفُونَ مِنهُ فَتَسخَرُونَ مِنَ المَارَّةِ.\nمَصَانِعَقُصُورًا مَنِيعَةً وَحُصُونًا مُشَيَّدَةً.\nأَمَدَّكُمأَعطَاكُم وَأَنعَمَ عَلَيكُم.\nسَوَاءٌ عَلَينَايَستَوِي عِندَنَا.\ndeeds\nاذهب إلى الضعفاء والفقراء الصالحين وجالسهم، وقدم لهم الهدايا.\nادع الله تعالى أن يهلك الظالمين بالظالمين، وأن يخرج المسلمين من بينهم سالمين.\nاستمع إلى موعظة من المواعظ، وطبق ما سمعته.\nguid\nالظلمة والطغاة إذا أعيتهم الحجج؛ لجأوا إلى القوة.\nمشروعية طلب الفتح من الله عند اشتداد الظلم.\nلما كان صبر نوح طويلًا كانت استجابة الله له سريعة.\nrefl\nقَالَ وَمَا عِلۡمِي بِمَا كَانُواْ يَعۡمَلُونَ ١١٢\nقال نوح لقومه: وما علمي بما كان أتباعي يعملون، إنَّما لي منهم ظاهر أمرهم دون باطنه، ولم أكلف علم باطنهم، وإنَّما كلفت الظاهر؛ فمن أظهر حسنًا ظننت به حسنًا، ومن أظهر سيئًا ظننت به سيئًا. يقول: إنَّ حساب باطن أمرهم الذي خفي عني إلا على ربي لو تشعرون؛ فإنه يعلم سر أمرهم وعلانيته. الطبري:١٩/٣٧٠.\nالداعية مسؤول عن ظاهر أحوال الناس، وليس مكلفًا بالعلم ببواطنهم، وضح ذلك من الآية.\nوَمَآ أَنَا۠ بِطَارِدِ ٱلۡمُؤۡمِنِينَ ١١٤ إِنۡ أَنَا۠ إِلَّا نَذِيرٞ مُّبِينٞ ١١٥\nوكأنهم طلبوا منه طرد الضعفاء كما طلبته قريش. ﴿إِنۡ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ﴾ يعنى: إن الله ما أرسلني أخص ذوي الغنى دون الفقراء، إنَّما أنا رسول أبلغكم ما أرسلت به، فمن أطاعني فذلك السعيد عند الله وإن كان فقيرًا. القرطبي:١٦/٥٣.\nهل الدعوة خاصة بالأغنياء؟ وضح ذلك من خلال الآية.\nأَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ ١٢٨\nومقام الموعظة أوسع من مقام تغيير المنكر؛ فموعظة هود -عليه السلام- متوجهة إلى ما في نفوسهم من الأدواء الروحية، وليس في موعظته أمر بتغيير ما بنَوه من العلامات ولا ما اتخذوه من المصانع. ابن عاشور:١٩/١٦٦.\nهل أنكر هود -عليه السلام- على قومه بناء المباني؟\nأَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ ١٢٨ وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ ١٢٩ وَإِذَا بَطَشۡتُم بَطَشۡتُمۡ جَبَّارِينَ ١٣٠\nدل توبيخه -عليه السلام- إياهم بما ذكر على استيلاء حب الدنيا والكبر على قلوبهم؛ حتى أخرجهم ذلك عن حد العبودية. الألوسي:١٠/١٠٨.\nما أثر المبالغة في حب الدنيا؟\nأَمَدَّكُم بِأَنۡعَٰمٖ وَبَنِينَ ١٣٣\nابتدأ في تعداد النعم بذكر الأنعام؛ لأنها أجلّ نعمة على أهل ذلك البلد؛ لأن منها أقواتَهم، ولباسهم، وعليها أسفارهم. ابن عاشور:١٩/١٧٠.\nلماذا ابتدئ بذكر الأنعام في الآية الكريمة؟\nقَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ ١٣٦\nكانت عاد قد بلغوا مبلغًا عظيمًا من البأس وعظم السلطان والتغلب على البلاد مما أثار قولهم: ﴿مَنۡ أَشَدُّ مِنَّا قُوَّةً﴾ [فصلت: ١٥]... فطال عليهم الأمد، وتفننوا في إرضاء الهوى، وأقبلوا على الملذات واشتد الغرور بأنفسهم فأضاعوا الجانب الأهم للإنسان وهو جانب الدين وزكاء النفس... واستخفوا بجانب الله تعالى، واستحمقوا الناصحين. ابن عاشور:١٩/١٦٥.\nبيّن خطورة كثرة النعم على المجتمع الغافل عن ذكر الله.\nقَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ ١٣٦\n﴿قَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ﴾ كل ذلك عندنا سواء؛ لا نسمع منك، ولا نلوي على ما تقوله. القرطبي:١٦/٥٩.\nبيّن حال قساة القلوب إذا وعظوا وذكروا بالله تعالى."],[373,"§الشعراء\nwords\nخُلُقُدِينُ، وَعَادَةُ.\nطَلعُهَا هَضِيمٌثَمَرُهَا يَانِعٌ لَيِّنٌ نَضِيجٌ.\nفَارِهِينَمَاهِرِينَ بِنَحتِهَا أَشِرِينَ بَطِرِينَ.\nالمُسرِفِينَالمُتَمَادِينَ فِي مَعصِيَةِ اللهِ.\nشِربٌنَصِيبٌ مِنَ المَاءِ.\nفَعَقَرُوهَانَحَرُوهَا.\ndeeds\nأرسل رسالة بالهاتف الجوال تذكر فيها الدعاة أن من أسباب نجاح دعوتهم إخلاصهم، وعدم إرادة الدنيا في دعوتهم.\nعلّم مسلمًا بعض أذكار اليوم والليلة محتسبًا في ذلك الأجر من الله.\nاكتب رسالة تبين فيها خطر الكفار والمنافقين، ومظاهر إفسادهم في الأرض.\nguid\nلا تأبه باحتقار المكذبين وسخريتهم؛ فهذه حيلة الضعفاء الجاهلين.\nالأمانة شعار الرسل والدعاة الصادقين في كل الأمم والعصور.\nالتحذير من طاعة المسرفين في الذنوب والمعاصي؛ لخطورة عاقبة طاعتهم.\nrefl\nفَكَذَّبُوهُ فَأَهۡلَكۡنَٰهُمۡۚ\nقد بين سبب إهلاكه إياهم في غير موضع من القرآن؛ بأنه أرسل عليهم ريحًا صرصرًا عاتيةً؛ أي: ريحًا شديدة الهبوب، ذات برد شديد جدًّا، فكان إهلاكهم من جنسهم، فإنهم كانوا أعتى شيء وأجبره، فسلط الله عليهم ما هو أعتى منهم وأشد قوة. ابن كثير:٣/٣٣١.\n(الجزاء من جنس العمل) وضِّح هذه المقولة من خلال عقوبة عاد؛ قوم هود.\nكَذَّبَتۡ ثَمُودُ ٱلۡمُرۡسَلِينَ ١٤١\nكذبوا صالحًا -عليه السلام- الذي جاء بالتوحيد الذي دعت إليه المرسلون؛ فكان تكذيبهم له تكذيبًا للجميع. السعدي:٥٩٦\nكيف حصل من قوم ثمود التكذيب بجميع المرسلين؟\nوَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ١٤٥\nفتقولون: يمنعنا من اتباعك، أنك تريد أخذ أموالنا، ﴿إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ﴾ أي: لا أطلب الثواب إلا منه. السعدي:١/٥٩٦.\nما علامة صدق أولياء الله الصادقين المذكورة في الآية؟\nأَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ ١٤٦\n(أتتركون): تخويف لهم معناه: أتطمعون أن تتركوا في النعم على كفركم. ابن جزي:٢/١٢١.\nهل يستمر دوام الحال إذا اجتمع النعيم مع المعاصي في المجتمع؟\nأَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ ١٤٦\nآمنين حال مبينة لبعض ما أجمله قوله: ﴿فِي مَا هَٰهُنَآ﴾؛ وذلك تنبيه على نعمة عظيمة لا يدل عليها اسم الإشارة لأنها لا يشار إليها؛ وهي نعمة الأمن التي هي من أعظم النعم ولا يتذوق طعم النعم الأخرى إلا بها. ابن عاشور:١٩/١٧٥.\nلماذا كانت نعمة الأمن من النعم العظيمة؟\nٱلَّذِينَ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ ١٥٢\nولما كان (يفسدون) لا ينافي إصلاحهم أحيانا؛ أردف بقوله تعالى: ﴿وَلَا يُصۡلِحُونَ﴾ لبيان كمال إفسادهم، وأنه لم يخالطه إصلاح أصلًا. الألوسي:١٠/١١٢.\nما فائدة الجمع بين الوصف بالإفساد، وعدم الإصلاح؟\nفَأَخَذَهُمُ ٱلۡعَذَابُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ١٥٨\nوذلك أن الريح كانت تأتي الرجل منهم فتقتلعه وترفعه في الهواء، ثم تنكسه على أم رأسه فتشدخ دماغه، وتكسر رأسه، وتلقيه؛ كأنهم أعجاز نخل منقعر. وقد كانوا تحصنوا في الجبال والكهوف والمغارات، وحفروا لهم في الأرض إلى أنصافهم، فلم يغن عنهم ذلك من أمر الله شيئًا، ﴿إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۚ﴾. ابن كثير:٦/١٥٥.\nبيّن صفة عذاب ثمود قوم صالح."],[374,"§الشعراء\nwords\nعَادُونَمُتَجَاوِزُونَ مَا أَبَاحَهُ اللهُ لَكُم مِنَ الحَلاَلِ إِلَى الحَرَامِ.\nالقَالِينَالمُبغِضِينَ لِعَمَلِكُم بُغضًا شَدِيدًا.\nالغَابِرِينَالبَاقِينَ فِي العَذَابِ.\nأَصحَابُ الأَيكَةِأَصحَابُ الأَرضِ ذَاتِ الشَّجَرِ المُلتَفِّ؛ وَهُم قَومُ شُعَيبٍ.\nالمُخسِرِينَالنَّاقِصِينَ لِحُقُوقِ النَّاسِ.\nبِالقِسطَاسِبِالمِيزَانِ.\ndeeds\nقل: اللهم كرِّه إليّ الكفر والفسوق والعصيان.\nانهَ عن منكر ثم أرسل رسالة تبين فيها أنه إذا تساهلت الأمة في الأمر بالمعروف والنهي عن المنكر انتشر فيها الأمر بالمنكر والنهي عن المعروف -والعياذ بالله-.\nاكتب كلمة عن خطر التطفيف في الوزن، وعقوبته، ووزعها على الباعة الذين في حيّك.\nguid\nإذا عدمت محبة الله في القلب فحدث ولا حرج عن انعدام الفطرة.\nاستجابة دعوة المظلوم؛ لا سيما إن كان من الصالحين.\nتوقع العذاب إذا انتشر الشر، وعِظَم الظلم والفساد.\nrefl\nأَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ ١٦٥\nوالمعنى: ﴿أَتَأۡتُونَ ٱلذُّكۡرَانَ﴾ مخالفين جميع العالمين من الأنواع التي فيها ذكور وإناث؛ فإنها لا يوجد فيها ما يأتي الذكور. فهذا تنبيه على أن هذا الفعل الفظيع مخالف للفطرة، لا يقع من الحيوان العُجم، فهو عمل ابتدعوه ما فعله غيرهم. ابن عاشور:١٩/١٧٩.\nكيف بينت الآية الكريمة فظاعة عمل قوم لوط؟\nقَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِينَ ١٦٧\nقالوا كما قال من قبلهم؛ تشابهت قلوبهم في الكفر فتشابهت أقوالهم. السعدي:٥٩٦.\nعلى ماذا يدل تشابه الأقوال بين المجرمين قديمًا وحديثًا؟\nقَالَ إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ ١٦٨\nقال لوط -عليه السلام-: ﴿إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ﴾، والقلي: بغضه وهجره، والأنبياء أولياء الله؛ يحبون ما يحب، ويبغضون ما يبغض. ابن تيمية: ٥/٤٩.\nبيّن من الآية صفة من أهم صفات أولياء الله.\nرَبِّ نَجِّنِي وَأَهۡلِي مِمَّا يَعۡمَلُونَ ١٦٩\n﴿رَبِّ نَجِّنِي وَأَهۡلِي مِمَّا يَعۡمَلُونَ﴾ أي: من عذاب عملهم؛ دعا الله لمَّا آيس من إيمانهم ألا يصيبه من عذابهم. القرطبي:١٦/٦٩.\nبيّن شدة خوف نبي الله لوط -عليه السلام- من نزول العذاب.\nفَنَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ ١٧٠ إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ ١٧١\n﴿إِلَّا عَجُوزًا﴾ وهي امرأته، كائنة (في) حكم (الغابرين) أي: الماكثين الذين تلحقهم الغبرة بما يكون من الداهية، فإننا لن [نُنجِيَها] لقضائنا بذلك في الأزل؛ لكونها لم تتابعه في الدين، وكان هواها مع قومها. البقاعي:١٤/٨٣.\nصلة الدين أقوى من صلة النسب، وضح ذلك من الآية.\nإِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ١٧٨ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ١٧٩ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ١٨٠\nوإنَّما كانت دعوة هؤلاء الأنبياء كلهم فيما حكى الله عنهم على صيغة واحدة لاتفاقهم على الأمر بالتقوى والطاعة والإخلاص في العبادة، والامتناع من أخذ الأجر على الدعوة، وتبليغ الرسالة. البغوي:٣/٣٧١.\nما الصفات التي اشترك فيها الرسل -عليهم السلام- في دعوتهم؟\nأَوۡفُواْ ٱلۡكَيۡلَ وَلَا تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ ١٨١ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ ١٨٢\nوالمراد: الأمر بوفاء الوزن وإتمامه، والنهي عن النقص دون النهي عن الزيادة، والظاهر أنه لم ينه عنها، ولم يؤمر بها في الكيل والوزن، وكأن ذلك دليل على أن من فعلها فقد أحسن، ومن لم يفعلها فلا عليه. الألوسي:١٠/١١٧.\nماذا يفيد السكوت عن الزيادة في الكيل والوزن؟"],[375,"§الشعراء\nwords\nوَالجِبِلَّةَالخَلِيقَةَ وَالأُمَمَ المَاضِينَ.\nالمُسَحَّرِينَمَن أَصَابَهُم سِحرٌ شَدِيدٌ، فَذَهَبَ بِعُقُولِهِم.\nكِسَفًاقِطَعًا مِنَ العَذَابِ.\nالظُّلَّةِسَحَابَةٍ أَظَلَّتهُم وَجَدُوا تَحتَهَا بَردًا، فَلمَّا اجتَمَعُوا أَحرَقَتهُم بِنَارِهَا.\nزُبُرِ الأَوَّلِينَكُتُبِ الأَنبِيَاءِ السَّابِقِينَ.\nالأَعجَمِينَالَّذِينَ لاَ يَتَكَلَّمُونَ العَرَبِيَّةَ.\ndeeds\nاقرأ قصة قوم شعيب في أكثر من موضع من القرآن الكريم وتأمل ما فيها من فوائد.\nاكتب رسالة تنصح فيها مسلمًا بتذكيره بآية من آيات القرآن الكريم.\nادرس متنًا في اللغة العربية بنية تفهم كتاب الله تعالى.\nguid\nأنذر جلساءك بما تحفظـه وتفهمـه من معـاني القـرآن الكـريم.\nموت القلب يجعل المرء يستبعد وقوع العذاب عليه.\nمهما كثر التمتع وطال الزمان، فليس ذلك بمغن للعبد عن الحساب والجزاء.\nrefl\nفَأَسۡقِطۡ عَلَيۡنَا كِسَفٗا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ١٨٧ قَالَ رَبِّيٓ أَعۡلَمُ بِمَا تَعۡمَلُونَ ١٨٨ فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ يَوۡمِ ٱلظُّلَّةِۚ\nهذا من جنس ما سألوه من إسقاط الكسف عليهم؛ فإن الله -سبحانه وتعالى- جعل عقوبتهم أن أصابهم حر عظيم مدة سبعة أيام لا يكنهم منه شيء، ثم أقبلت إليهم سحابة أظلتهم، فجعلوا ينطلقون إليها، يستظلون بظلها من الحر؛ فلما اجتمعوا كلهم تحتها أرسل الله تعالى عليهم منها شررًا من نار ولهبًا ووهجًا عظيمًا، ورجفت بهم الأرض، وجاءتهم صيحة عظيمة أزهقت أرواحهم. ابن كثير:٣/٣٣٥.\nكان عذاب قوم شعيب من جنس ما سألوه من العذاب، وضِّح ذلك.\nإِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ١٩٠\nفإن قيل: لم كرر قوله: ﴿إِنَّ فِي ذَٰلِكَ لَأٓيَةً﴾ مع كل قصة؟ فالجواب: أن ذلك أبلغ في الاعتبار، وأشدّ تنبيهًا للقلوب، وأيضًا فإن كل قصة منها كأنها كلام قائم مستقل بنفسه، فختمت بما ختمت به صاحبتها. ابن جزي:٢/١٢٣.\nما الفائدة من تكرار قوله: ﴿إِنَّ فِي ذَٰلِكَ لَأٓيَةًۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ﴾ في كل مقطع من السورة؟\nوَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ ١٩٢\nفالذي أنزله فاطر الأرض والسماوات، المربِّي جميع العالم العلوي والسفلي، وكما أنه رباهم بهدايتهم لمصالح دنياهم وأبدانهم فإنه يربيهم أيضًا بهدايتهم لمصالح دينهم وأخراهم، ومن أعظم ما رباهم به: إنزال هذا الكتاب الكريم الذي اشتمل على الخير الكثير والبر الغزير، وفيه من الهداية لمصالح الدارين والأخلاق الفاضلة ما ليس في غيره. السعدي:٥٩٧-٥٩٨.\nما الفائدة من وصف الله في هذا الموضع بأنه رب العالمين؟\nوَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ ١٩٢ نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ ١٩٣ عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِينَ ١٩٤ بِلِسَانٍ عَرَبِيّٖ مُّبِينٖ ١٩٥\nتأمل كيف اجتمعت هذه الفضائل الفاخرة في هذا الكتاب الكريم؛ فإنه أفضل الكتب، نزل به أفضل الملائكة، على أفضل الخلق، على أفضل بُضعَةٍ فيه؛ وهي قلبه، على أفضل أمةٍ أخرجت للناس، بأفضل الألسنة وأفصحها وأوسعها؛ وهو اللسان العربي المبين. السعدي:٥٩٨.\nتحدث عن الفضائل المجتمعة في هذا القرآن الكريم.\nأَوَ لَمۡ يَكُن لَّهُمۡ ءَايَةً أَن يَعۡلَمَهُۥ عُلَمَٰٓؤُاْ بَنِيٓ إِسۡرَٰٓءِيلَ ١٩٧\nفإن كل شيء يحصل به اشتباه يرجع فيه إلى أهل الخبرة والدراية، فيكون قولهم حجة على غيرهم؛ كما عرف السحرة الذين مهروا في علم السحر صدق معجزة موسى، وأنه ليس بسحر؛ فقول الجاهلين بعد هذا لا يؤبه به. السعدي:٥٩٨.\nلماذا خصَّ علم علماء بني إسرائيل بأنه دليلٌ كافٍ على صدق هذا القرآن؟\nفَيَقُولُواْ هَلۡ نَحۡنُ مُنظَرُونَ ٢٠٣\nأي: لنؤمن ونصدق؛ يتمنون الرجعة والنظرة. البغوي:٣/٣٧٣.\nأي شيء يتمنى المكذب إذا نزل العذاب؟\nأَفَرَءَيۡتَ إِن مَّتَّعۡنَٰهُمۡ سِنِينَ ٢٠٥\nالمعنى: أن مدّة إمهالهم لا تغني مع نزول العذاب بعدها، وإن طالت مدة سنين؛ لأن كل ما هو آت قريب. ابن جزي:٢/ ١٢٤.\nهل يغني الإنسان طول العمر إن استمرّ على المعاصي؟"],[376,"§الشعراء\nwords\nالسَّمعِاستِمَاعِ القُرآنِ مِنَ السَّمَاءِ.\nلَمَعزُولُونَلَمَحجُوبُونَ مَرجُومُونَ بِالشُّهُبِ.\nوَاخفِض جَنَاحَكَأَلِن جَانِبَكَ وَكَلامَكَ تَوَاضُعًا.\nأَفَّاكٍكَذَّابٍ.\nأَثِيمٍكَثِيرِ الآثَامِ.\nوَادٍفَنٍّ مِن فُنُونِ البَاطِلِ، وَالكَذِبِ.\nيَهِيمُونَيَخُوضُونَ.\nمُنقَلَبٍمَرجِعٍ.\ndeeds\nتعاون مع بعض أقاربك في عمل برنامج دعوي تفيد فيه أقاربك بكلمة طيبة وهدية محببة.\nقم الليل، وأطل السجود.\nاذكر الله تعالى بالأذكار المطلقة والمقيدة؛ مثل قَول: \"سبحان الله وبحمده\" مائة مرة، والاستغفار سبعين مرة.\nguid\nمن مات يدعو غير الله فهو مع المعذبين.\nلا نجاح للداعية إلا بالحلم، والتواضع، ولين الجانب.\nاحذر الظلم وتذكر سوء عاقبة أهله، وتأمل في حال من حولك ممن طغا وتجبر؛ كيف قصمهم الله تعالى.\nrefl\nمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يُمَتَّعُونَ ٢٠٧\nيقول تعالى ذكره: ثم جاءهم العذاب الذي كانوا يوعدون على كفرهم بآياتنا، وتكذيبهم رسولنا. ﴿مَآ أَغۡنَىٰ عَنۡهُم﴾ يقول: أي شيء أغنى عنهم التأخير الذي أخرنا في آجالهم، والمتاع الذي متعناهم به من الحياة، إذ لم يتوبوا؟! هل زادهم تمتيعنا إياهم ذلك إلا خبالًا؟! وهل نفعهم شيئًا؟! بل ضرهم بازديادهم من الآثام، واكتسابهم من الإجرام ما لو لم يُمتَّعوا لم يكتسبوه. الطبري:١٩/٤٠٢.\nطول العمر بدون عمل صالح هلاك وعذاب؛ بيّن ذلك.\nفَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِينَ ٢١٣\nخوطب به النبي -صلى الله عليه وسلم- مع استحالة صدور المنهي عنه -عليه الصلاة والسلام- تهييجًا وحثًّا لازدياد الإخلاص؛ فهو كناية عن: \"أخلص في التوحيد حتى لا ترى معه -عز وجل- سواه\". وفيه لطف لسائر المكلفين ببيان أن الإشراك من القبح والسوء بحيث ينهى عنه من لم يمكن صدوره عنه؛ فكيف بمن عداه. الألوسي:١٠/١٣١.\nما فائدة مخاطبة النبي -صلى الله عليه وسلم- بالنهي عن الشرك مع استحالة صدوره عنه؟\nوَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ ٢١٤\nوهذا لا ينافي أمره بإنذار جميع الناس؛ كما إذا أُمِرَ الإنسانُ بعموم الإحسان، ثم قيل: \"أحسن إلى قرابتك\"؛ فيكون هذا خصوصًا دالًا على التأكيد، وزيادة الحق. السعدي:٥٩٩.\nهل يفهم من هذه الآية أن دعوة النبي -صلى الله عليه وسلم- خاصة بقومه؟\nوَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ ٢١٥ فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ ٢١٦\n﴿فَإِنۡ عَصَوۡكَ﴾... هذا لدفع احتراز وهم من يتوهم أن قوله: ﴿وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ﴾ يقتضي الرضاء بجميع ما يصدر منهم ما داموا مؤمنين؛ فدفع هذا بهذا. السعدي:٥٩٩.\nلماذا عَقّب قوله: ﴿فَإِنۡ عَصَوۡكَ﴾ بعد قوله: ﴿وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ﴾؟\nوَتَقَلُّبَكَ فِي ٱلسَّٰجِدِينَ ٢١٩\nمعناه: يرى صلاتك مع المصلين؛ ففي ذلك إشارة إلى الصلاة مع الجماعة. ابن جزي:٢/١٢٤.\nكيف دلّت هذه الآية على صلاة الجماعة؟\nيُلۡقُونَ ٱلسَّمۡعَ وَأَكۡثَرُهُمۡ كَٰذِبُونَ ٢٢٣\n(يلقون): بمعنى: يلقون المسموع، والضمير يحتمل أيضًا على هذا أن يكون للشياطين؛ لأنهم يلقون الكلام إلى الكهان، أو يكون للكهان؛ لأنهم يلقون الكلام إلى الناس، ﴿وَأَكۡثَرُهُمۡ كَٰذِبُونَ﴾ يعني: الشياطين، أو الكهان؛ لأنهم يكذبون فيما يخبرون به عن الشياطين. ابن جزي:٢/١٢٥.\nمن أين جاء كذب الكهنة والعرافين؟\nأَلَمۡ تَرَ أَنَّهُمۡ فِي كُلِّ وَادٖ يَهِيمُونَ ٢٢٥\nيقول: في كل لغو يخوضون، ولا يتبعون سنن الحق؛ لأن من اتبع الحق، وعلم أنه يكتب عليه ما يقوله؛ تثبت ولم يكن هائمًا يذهب على وجهه لا يبالى ما قال. القرطبي:١٦/٩٥.\nما تقول فيمن يخوض مع كل خائض، ويتكلم بما شاء، ولا يتبع الحق؟"],[377,"§النمل\nwords\nيَعمَهُونَيَتَرَدَّدُونَ فِي أَعمَالِهِمُ القَبِيحَةِ مُتَحَيِّرِينَ.\nلَتُلَقَّىلَتَتَلَقَّى.\nمِن لَدُنمن عِندِ.\nآنَستُأَبصَرتُ.\nبِشِهَابٍقَبَسٍ بِشُعلَةِ نَارٍ.\nتَصطَلُونَتَستَدفِئُونَ بِهَا مِنَ البَردِ.\nمُبصِرَةًظَاهِرَةً بَيِّنَةً.\ndeeds\nأقم الصلوات في المسجد بخشوعها، وواجباتها، وسننها.\nتصدق على أحد المحتاجين.\nادع الله تعالى باسميه: (العليم) و(الحكيم) أن يرزقك العلم والحكمة، وحفظ القرآن.\nguid\nبيان إعجاز القرآن؛ إذ آياته مؤلفة من مثل: (طس) و(حم)، وعجز الخلق عن تأليف مثله.\nأقم الصلاة بأركانها وواجباتها وشروطها وخشوعها؛ حتى تستطيع الإفادة من آيات هذا القرآن.\nإنكار البعث والدار الآخرة يجعل صاحبه شر الخليقة، وأسوأ حالًا من البهائم.\nrefl\nهُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ ٢ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ\nربما قيل: لعله يكثر مُدَّعُو الإيمان؛ فهل يُقبل من كل أحد ادَّعى أنه مؤمن ذلك؟ أم لا بد لذلك من دليل؟ وهو الحق؛ فلذلك بيَّن تعالى صفة المؤمنين فقال: (الذين يقيمون الصلاة). السعدي:٦٠١.\nما علامة صدق مدعي الإيمان؟\nوَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ ٣\nويقينهم بالآخرة يقتضي كمال سعيهم لها، وحذرهم من أسباب العذاب وموجبات العقاب؛ وهذا أصل كل خير. السعدي:٦٠١.\nما الذي يقتضيه الإيمان باليوم الآخر؟\nإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ ٤\nتلكَ الأعمال هي أَعمال الإشراك الظَّاهرةُ والباطنةُ؛ فَهم لإلفهِم إِيَّاها وتصلُّبهِم فيها صاروا غَير قَابلين لهَديِ هذا الكتاب الَّذي جاءتهم آياته. ابن عاشور:١٩/٢٢٠.\nمن خلال الآية: بين عاقبة الإصرار على الخطأ.\nإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ ٤\n﴿إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ﴾ أي: [لا] يوجدون الإيمان ويجددونه ﴿بِٱلۡأٓخِرَةِ زَيَّنَّا﴾ أي: بعظمتنا التي لا يمكن دفاعها ﴿لَهُمۡ أَعۡمَٰلَهُمۡ﴾ أي: القبيحة، حتى أعرضوا عن الخوف من عاقبتها مع ظهور قباحتها. البقاعي:١٤/١٢٧.\nماذا يترتب على ضعف الإيمان بالآخرة؟\nإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ ٤\nالشيطان مزين لهم بالوسوسة التي تجد قبولًا في نفوسهم؛ كما قال تعالى حكاية عنه قال: ﴿قَالَ فَبِعِزَّتِكَ لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ٨٢ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ﴾ [ص: ٨٢، ٨٣]... وأفادت صيغة المضارع أن العمه متجدد مستمر فيهم؛ أي فهم لا يرجعون إلى اهتداء لأنهم يحسبون أنهم على صواب... واعلم أن هذا الاستمرار متفاوت الامتداد: فمنه أشده وهو الذي يمتد بصاحبه إلى الموت، ومنه دون ذلك، وكلُّ ذلك على حسب تزيين الكفر في نفوسهم. ابن عاشور:١٩/٢٢١.\nبينت الآية مدخلًا من مداخل الشيطان على الإنسان، فما هو؟\nوَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰ لَا تَخَفۡ إِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ ١٠\nوالتقييد بــ(لدي) لأن المرسلين في سائر الأحيان أخوف الناس من الله -عز وجل-؛ فقد قال تعالى: ﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْ﴾ [فاطر: ٢٨]، ولا أعلم منهم بالله تعالى شأنه. الألوسي:١٠/١٥٩.\nما سر التقييد بِـ (لديَّ)؟\nيَٰمُوسَىٰ لَا تَخَفۡ إِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ ١٠ إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ سُوٓءٖ فَإِنِّي غَفُورٞ رَّحِيمٞ ١١\nفإن قال قائل: فما معنى الخوف بعد التوبة والمغفرة؟ قيل له: هذه سبيل العلماء بالله -عز وجل-؛ أن يكونوا خائفين من معاصيهم وَجِلين، وهم أيضًا لا يأمنون أن يكون قد بقي من أشراط التوبة شيء لم يأتوا به؛ فهم يخافون من المطالبة به. القرطبي:١٦/٣٣٠.\nلماذا يخاف الصالحون من ذنوبهم بعد استغفارهم؟"],[378,"§النمل\nwords\nيُوزَعُونَيُرَدُّ أَوَّلُ كُلِّ جِنسٍ عَلَى آخِرِهِم لِيَقِفُوا جَمِيعًا مُنتَظِمِينَ.\nأَوزِعنِيأَلهِمنِي.\nفَمَكَثَ غَيرَ بَعِيدٍبَقِيَ زَمَنًا غَيرَ طَوِيلٍ.\nسَبَإٍمَدِينَةٍ بِاليَمَنِ.\ndeeds\nتذكر ثلاث نعم اختصك الله بها، ثم اشكر الله تعالى عليها اقتداء بالأنبياء.\nتأمل حياة النمل، أو استمع إلى برنامج علمي عن حياتها، ثم اكتب ثلاث فوائد من تلك المشاهدة.\nقل: \"رب أزعني أن أشكر نعمتك التي أنعمت عليَّ وعلى والديَّ، وأن أعمل صالحًا ترضاه، وأدخلني برحمتك في عبادك الصالحين\".\nguid\nتَبَسَّم في المواضع التي يحسن فيها التبسم، وإياك وجهامة الوجه الدائم.\nإذا أنعم الله بنعمةٍ على أحد والديك فاشكره عليها؛ فإن النعمة على الوالد نعمةٌ على الولد، والحمد والشكر من أسباب دوام النعم.\nمن ولاّه الله أمرًا من الأمور فمن تقوى الله أن يتفقد ما تولاه ويرعاه.\nrefl\nفَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ١٤\nوفحوى الخطاب يقول: احذروا أيها المكذبون لمحمد، الجاحدون لما جاء به من ربه أن يصيبكم ما أصابهم بطريق الأولى والأحرى؛ فإن محمدًا -صلى الله عليه وسلم- أشرف وأعظم من موسى، وبرهانه أدل وأقوى من برهان موسى. ابن كثير:٣/٣٤٥-٣٤٦.\nفي هذه الآية تحذيرٌ لمن يكفر بنبوة محمد -صلى الله عليه وسلم- مع أن الكلام عمَّن كفر بموسى، وضِّح ذلك.\nوَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي فَضَّلَنَا عَلَىٰ كَثِيرٖ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِينَ ١٥\nوهذا عنوان سعادة العبد: أن يكون شاكرًا لله على نعمه الدينية والدنيوية، وأن يرى جميع النعم من ربه؛ فلا يفخر بها، ولا يعجب بها، بل يرى أنها تستحق عليه شكرًا كثيرًا. السعدي:٦٠٢.\nفي ضوء هذه الآية: وضح أثر النعم على الصالحين.\nوَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ\nأي: في الملك والنبوة، وليس المراد وراثة المال؛ إذ لو كان كذلك لم يخص سليمان وحده من بين سائر أولاد داود... فإن الأنبياء لا تورث أموالهم. ابن كثير:٣٤٦.\nمن أجمل ما يرث الولد من أبيه الإيمان والعلم والحكمة، بيّن ذلك من خلال الآية.\nفَتَبَسَّمَ ضَاحِكٗا مِّن قَوۡلِهَا\nقال الزجاج: \"أكثر ضحك الأنبياء التبسم\"، وقوله: ضاحكًا أي: مبتسمًا. البغوي:٣/٣٩١.\nكيف كان ضحك الأنبياء -عليهم الصلاة والسلام-؟\nوَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَا لِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَآئِبِينَ ٢٠ لَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ ٢١\nفي هذه الآية دليل على تفقد الإمام أحوال رعيته، والمحافظة عليهم؛ فانظر إلى الهدهد مع صغره كيف لم يخف على سليمان حاله، فكيف بعظام الملك. ويرحم الله عمر؛ فإنه كان على سيرته، قال: \"لو أن سخلة على شاطئ الفرات أخذها الذئب ليسأل عنها عمر\". القرطبي:١٦/١٣١.\nهل الإمارة تشريف وفخر أم أمانة ومسؤولية يُسأل عنها صاحبها؟ بين هذا من الآية.\nلَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ ٢١\nأي: حجة واضحة على تخلفه. وهذا من كمال ورعه وإنصافه؛ أنه لم يقسم على مجرد عقوبته بالعذاب أو القتل؛ لأن ذلك لا يكون إلا من ذنب، وغيبته قد تحتمل أنها لعذر واضح؛ فلذلك استثناه لورعه وفطنته. السعدي:٦٠٤.\nكيف تدل الآية على ورع سليمان وتأنيه وعدم استعجاله؟\nفَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۢ بِنَبَإٖ يَقِينٍ ٢٢\nفي هذه المكافحة التنبيه على أن أضعف الخلق قد يؤتى ما لا يصل إليه أقواهم؛ لتتحاقر إلى العلماء علومهم، ويردوا العلم في كل شيء إلى الله، وفيه إبطال لقول الرافضة إن الإمام لا يخفى عليه شيء، ولا يكون في زمانه من هو أعلم منه. البقاعي:١٤/١٥٠.\nما الذي يدل عليه معرفة الهدهد لمَّا غاب عن سليمان -عليه السلام- مع سعة علمه وملكه؟"],[379,"§النمل\nwords\nالخَبءَالمَخبُوءَ المَستُورَ عَنِ الأَعيُنِ.\nالمَلأُأَشرَافُ النَّاسِ.\nتَعلُوا عَلَيَّتَتَكَبَّرُوا عَلَيَّ.\nأَفتُونِيأَشِيرُوا عَلَيَّ.\nقَاطِعَةً أَمرًاقَاضِيَةً حُكمًا وَفَاصِلَةً فِيهِ.\nتَشهَدُونِتَحضُرُونِي.\nأُولُوأَصحَابُ.\nفَنَاظِرَةٌمُنتَظِرَةٌ.\ndeeds\nتثبت اليوم من خبر سمعته؛ فإن التثبت من الأخبار منهج قرآني لا يغفل عنه الصالحون.\nأنكِر منكرًا رأيته في الحي؛ فهذا الهدهد أنكر الشرك بالله تعالى.\nقدّم هدية لمن تطمع في هدايته؛ لما فيها من توادّ القلوب.\nguid\nالعاقل يعرف ضعف المرأة، فلا يزج بها فيما لا يصلح لها من الأعمال.\nتذكر أن الشيطان يزين القبيح للغافلين عن ذكر الله، ويصد العبد عن طاعة الله تعالى.\nيستحب في تأليف الكتب والخطب والرسائل أن يُبتدأ فيها بالبسملة.\nrefl\nإِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ ٢٣ وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ ٢٤\nعن أَبي بَكرةَ -رضي الله عنه- قَال: لَمَّا بلَغ رسول الله -صلَّى الله علَيه وسلَّم- أنَّ أَهل فَارِس ملَّكُوا علَيهِم بنت كسرى قال: «لن يفلح قوم وَلَّوا أمرهم امرأة». البغوي:٣/٤٩٩.\nاستخرج فائدة من الآية.\nأَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ ٢٥\nأي: يعبدوا الذي له الكمال كله بالسجود الذي هو محل الأُنس، ومحط القرب، ودارة المناجاة، وآية المعافاة؛ فإنهم لو سجدوا له سبحانه لاهتدوا؛ فإن الصلاة تنهى عن الفحشاء والمنكر، ففات الشيطان ما يقصده منهم من الضلال. البقاعي:١٤/١٥٢-١٥٣.\nما أثر السجود لله في حياة الإنسان؟\n۞قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ ٢٧\nفي قوله: ﴿أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ﴾ دليل على أن الإمام يجب عليه أن يقبل عذر رعيته، ويدرأ العقوبة عنهم في ظاهر أحوالهم بباطن أعذارهم؛ لأن سليمان لم يعاقب الهدهد حين اعتذر إليه، وإنَّما صار صدق الهدهد عذرًا. البغوي:٣/٤٥٩.\nمن سنن الأنبياء التثبت من الأقوال، وضح ذلك من الآية.\nقَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ ٣٢\nواستدل بالآية على استحباب المشاورة والاستعانة بالآراء في الأمور المهمة. الألوسي: ١٠/١٩٢.\nكيف تتصرف في الأمور المهمة؟\nإِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ٣٠\nفيه: استحباب ابتداء الكتب بالبسملة كاملة. السعدي:٦٠٤.\nما المستحب في بداية الكتابة؟\nوَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ ٣٥\nقال قتادة: \"رحمها الله ورضي عنها، ما كان أعقلها في إسلامها وفي شركها! علمت أن الهدية تقع موقعًا من الناس\". وقال ابن عباس وغير واحد: \"قالت لقومها: إن قبل الهدية؛ فهو ملك فقاتلوه، وإن لم يقبلها؛ فهو نبي فاتبعوه\". ابن كثير:٦/١٩٠.\nالتعامل بحكمة قد يؤدي إلى الهداية، وضح ذلك من الآية.\nوَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ ٣٥\nقالت لقومها: إني أجرب هذا الرجل بهدية من نفائس الأموال، فإن كان ملكًا دنيويًا أرضاه المال، وإن كان نبيًا لم يرضه المال، وإنَّما يرضيه دخولنا في دينه؛ فبعثت إليه هدية عظيمة. ابن جزي:٢/ ١٣٠.\nكيف استطاعت ملكة سبأ أن تعرف صدق سليمان؟ وماذا تستفيد من هذا التصرف؟"],[380,"§النمل\nwords\nصَاغِرُونَمُهَانُونَ.\nعِفرِيتٌمَارِدٌ قَوِيٌّ شَدِيدٌ.\nنَكِّرُواغَيِّرُوا.\nالصَّرحَالقَصرَ، وَكَانَ صَحنُهُ مِن زُجَاجٍ تَحتَهُ مَاءٌ.\nمُمَرَّدٌمُمَلَّسٌ مُسَوّىً.\nمِن قَوَارِيرَمِن زُجَاجٍ صَافٍ.\ndeeds\nاكتب رسالة تبيّن فيها خطر تقديم الدنيا على الدين.\nألقِ كلمة، أو اكتب رسالة عبر الهاتف الجوال، تحذر فيها من الرشوة.\nتذكر ثلاثًا من النعم التي أنعم الله بها عليك، ثم اشكره عليها؛ حتى يبارك لك فيها.\nguid\nمقاييس أهل الآخرة تختلف عن مقاييس أهل الدنيا؛ ولذلك لا يفرحون بالدنيا كما يفرح بها أهلها.\nاعلم أن أجل النعم هي نعمة الدين، وأمَّا الدنيا؛ فهي إلى زوال، لا يركن المؤمن إليها.\nتأمل في اجتماع الوصفين: الغنى والكرم لله -عز وجل-.\nrefl\nفَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٖ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرٞ مِّمَّآ ءَاتَىٰكُمۚ\nإنَّما جعلت بلقيس قبول الهدية أو ردها علامة على ما في نفسها، على ما ذكرناه من كون سليمان ملكًا أو نبيًّا؛ لأنه قال لها في كتابه: ﴿أَلَّا تَعۡلُواْ عَلَيَّ وَأۡتُونِي مُسۡلِمِينَ﴾، وهذا لا تُقبل فيه فدية، ولا يؤخذ عنه هدية، وليس هذا من الباب الذي تقرر في الشريعة عن قبول الهدية بسبيل، وإنَّما هي رشوة وبيع الحق بالباطل؛ وهى الرشوة التي لا تحل. وأمَّا الهدية المطلقة للتحبب والتواصل فإنها جائزة من كل أحد وعلى كل حال. القرطبي:١٦/١٥٩.\nلِمَ ردَّ سليمان -عليه السلام- الهدية؟\nبَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ ٣٦\nفالمعنى: أنتم تفرحون بما يهدى إليكم لقصور همتكم على الدنيا، وحبكم الزيادة فيها؛ ففي ذلك من الحطِّ عليهم ما لا يخفى. الألوسي:١٠/١٩٥.\nالداعية إلى الحق والهدى لا ينبغي له الاغترار بزخرف الدنيا؛ كيف تستنبط هذا من الآية؟\nقَالَ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا\nقال أبو جعفر: وأولى الأقوال بالصواب في السبب الذي من أجله خصَّ سليمان بسؤاله الملأ من جنده بإحضاره عرش هذه المرأة دون سائر ملكها عندنا -ليجعل ذلك حجة عليها في نبوته، ويعرفها بذلك قدرة الله، وعظيم شأنه-؛ أنها خلفته في بيت في جوف أبيات؛ بعضها في جوف بعض، مغلق مقفل عليها؛ فأخرجه الله من ذلك كله بغير فتح أغلاق وأقفال، حتى أوصله إلى وليه من خلقه وسلمه إليه؛ فكان لها في ذلك أعظم حجة على حقيقة ما دعاها إليه سليمان، وعلى صدق سليمان فيما أعلمها من نبوته. الطبري:١٩/٤٦٣.\nلماذا طلب سليمان إحضار عرش الملكة دون سائر ملكها؟\nقَالَ عِفۡرِيتٞ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّي عَلَيۡهِ لَقَوِيٌّ أَمِينٞ ٣٩ قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ\nوهذه المناظرة بين العفريت من الجن والذي عنده علم من الكتاب ترمز إلى أنه يتأتى بالحكمة والعلم ما لا يتأتى بالقوة. ابن عاشور:١٩/٢٧١.\nكيف دلت الآية الكريمة على فضل العلم والحكمة؟\nفَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ\n﴿مِن فَضۡلِ رَبِّي﴾ أي: تفضُّلُه -جل شأنه- عليّ من غير استحقاق ذاتيٍّ لي له، ولا عمل مني يوجبه عليه -سبحانه وتعالى-. الألوسي:١٠/١٩٩.\nمن أعظم الشكر للنعمة نسبتها إلى المتفضل بها سبحانه. بين ذلك من الآية.\nفَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ\n﴿قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ﴾ أي: ليختبرني بذلك؛ فلم يغتر -عليه السلام- بملكه وسلطانه وقدرته كما هو دأب الملوك الجاهلين، بل عَلِم أن ذلك اختبار من ربه؛ فخاف أن لا يقوم بشكر هذه النعمة. ثم بين أن هذا الشكر لا ينتفع الله به، وإنَّما يرجع نفعه إلى صاحبه؛ فقال: ﴿وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ﴾. السعدي:٦٠٥.\nما الفارق الرئيس بين الملوك الصالحين والملوك الجاهلين؟\nوَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ ٤٠\n﴿وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ﴾ أي: يعود نفع شكره إليه؛ وهو أن يستوجب به تمام النعمة ودوامها؛ لأن الشكر قيد النعمة الموجودة وصيد النعمة المفقودة، ﴿وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّ﴾ عن شكره، (كريم) بالإفضال على من يكفر نعمه. البغوي:٣/٤٠٤.\nما فائدة شكر النعمة؟"],[381,"§النمل\nwords\nاطَّيَّرنَاتَشَاءَمنَا.\nطَائِرُكُم عِندَ اللهِمَا أَصَابَكُم مِن خَيرٍ، أَو شَرٍّ، فَاللهُ مُقَدِّرُهُ عَلَيكُم.\nتَقَاسَمُواحَلَفَ كُلُّ وَاحِدٍ مِنهُم لِلآخَرِ.\nلَنُبَيِّتَنَّهُلَنَأتِيَنَّهُ بِاللَّيلِ بَغتَةً فَنَقتُلَهُ.\nخَاوِيَةًخَالِيَةً.\ndeeds\nأرسل رسالة تبين فيها أن حكم الطيرة لا يرتبط بالطيور فقط، بل في كل شيء تتشاءم منه.\nاحفظ الدعاء الوارد في كراهية الطيرة؛ وهو قوله -صلى الله عليه وسلم-: «اللهم لا طير إلا طيرك، ولا خير إلا خيرك، ولا إله غيرك».\nادع الله أن يجعل ما يدبّره الكفار لأهل الإسلام تدميرًا لهم.\nguid\nالمؤمن دائمًا متفائل؛ فالفأل لا يأتي إلا بخير، وهو من كمال حسن الظن بالله.\nتذكر أن من مكر بالناس مكر الله به، وأن العاقبة السيئة راجعة عليه.\nيقيننا ثابت بنصرة الله تعالى لأوليائه وحفظه لهم.\nrefl\nقَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ ٤٧\n﴿قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ﴾ أي: ما يصيبكم من الخير والشر عند اللّه بأمره، وهو مكتوب عليكم؛ سمي طائرًا لسرعة نزوله بالإنسان؛ فإنه لا شيء أسرع من قضاء محتوم. البغوي:٣/٤٠٧\nلم سمي القضاء بالطائر؟\nقَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ ٤٧\nولا شيء أضر بالرأي ولا أفسد للتدبير من اعتقاد الطيرة، ومن ظن أن خوار بقرة أو نعيق غراب يرد قضاء أو يدفع مقدورًا؛ فقد جهل. القرطبي:١٦/١٨١.\nبيّن خطر الطيرة على الإنسان.\nقَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ ٤٧\n﴿قَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ﴾ زعموا -قبحهم الله- أنهم لم يروا على وجه صالح خيرًا، وأنه هو ومن معه من المؤمنين صاروا سببًا لمنع بعض مطالبهم الدنيوية، فقال لهم صالح: ﴿طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ﴾ أي: ما أصابكم إلا بذنوبكم، ﴿بَلۡ أَنتُمۡ قَوۡمٌ تُفۡتَنُونَ﴾ بالسراء والضراء، والخير والشر؛ لينظر هل تقلعون وتتوبون أم لا؟ السعدي:٦٠٦.\nما أسباب الحوادث والمصائب التي تقع على الإنسان؟\nوَمَكَرُواْ مَكۡرٗا وَمَكَرۡنَا مَكۡرٗا وَهُمۡ لَا يَشۡعُرُونَ ٥٠\nسمَّى الله تآمرهم مكرًا؛ لأنه كان تدبير ضُرٍّ في خفاءٍ. ابن عاشور:١٩/٢٨٤.\nلِمَ سُمِّي التآمر مكرًا في الآية الكريمة؟\nفَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ ٥٢\nوفي هذه الآية -على ما قيل- دلالة على أن الظلم يكون سببًا لخراب الدور. وروي عن ابن عباس أنه قال: \"أجد في كتاب الله تعالى أن الظلم يخرب البيوت\"، وتلا هذه الآية. وفي التوراة: \"ابن آدم لا تظلم يخرب بيتك\". قيل: وهو إشارة إلى هلاك الظالم؛ إذ خراب بيته متعقب هلاكه، ولا يخفى أنّ كون الظلم بمعنى الجور والتعدي على عباد الله تعالى سببًا لخراب البيوت مما شوهد كثيرًا في هذه الأعصار. الألوسي:١٠/٢٠٩.\nما أعظم عواقب الظلم؟\nفَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ ٥٢\nولمَّا خصَّ الله عملهم بوصف الظلم من بين عدة أحوال يشتمل عليها كفرهم؛ كالفساد؛ كان ذلك إشارة إلى أنَّ للظلم أثرًا في خراب بلادهم. ابن عاشور:١٩/٢٨٥.\nلمَ اقتصرت الآية الكريمة على ذكر الظلم من بين أسباب عذاب ثمود؟\nوَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ ٥٤\nأي: الفعلة الشنعاء التي تستفحشها العقول والفطر، وتستقبحها الشرائع. السعدي:٦٠٧.\nما وجه تسمية جريمة قوم لوط بالفاحشة؟"],[382,"§النمل\nwords\nقَدَّرنَاهَاجَعَلنَا امرَأَةَ لُوطٍ.\nالغَابِرِينَالبَاقِينَ فِي العَذَابِ.\nذَاتَ بَهجَةٍذَاتَ مَنظَرٍ حَسَنٍ.\nيَعدِلُونَيَجعَلُونَ للهِ عِدلًا وَنَظِيرًا.\nخِلاَلَهَاوَسَطَهَا.\nرَوَاسِيَجِبَالًا ثَوَابِتَ.\ndeeds\nادع الله تعالى أن يحبب إليك الإيمان، وأن يزينه في قلبك، وأن يكره إليك الكفر والفسوق والعصيان.\nأكثر اليوم ودائمًا من دعاء: \"ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إمامًا\".\nتذكر حاجة مِن حاجاتك صعبت عليك، وادع الله تعالى وألح عليه في الدعاء أن ييسرها لك.\nguid\nالظالمون إذا أعيتهم الحجج والبراهين يفزعون إلى القوة.\nالمرء إذا أدمن على معصية تصبح غير قبيحة عنده.\nسنة إنجاء الله أولياءه، وإهلاكه أعداءه.\nrefl\n۞فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ لُوطٖ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ٥٦\nالبلاء موكلٌ بالمنطق؛ فهم قالوا: ﴿أَخۡرِجُوٓاْ ءَالَ لُوطٍ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٌ يَتَطَهَّرُونَ﴾. ومفهوم هذا الكلام: وأنتم متلوثون بالخبث والقذر المقتضي لنُزول العقوبة بقريتكم ونجاة من خرج منها. السعدي:٦٠٧.\nكان منطقُ قوم لوط سببًا لهلاكهم، بَيِّن ذلك.\nفَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَٰهَا مِنَ ٱلۡغَٰبِرِينَ ٥٧\nأي: من الهالكين مع قومها؛ لأنها كانت ردءًا لهم على دينهم، وعلى طريقتهم في رضاها بأفعالهم القبيحة؛ فكانت تدل قومها على ضيفان لوط ليأتوا إليها، لا أنها كانت تفعل الفواحش؛ تكرمةً لنبي الله -صلى الله عليه وسلم- لا كرامة لها. ابن كثير:٣/٣٥٦.\nلماذا أُهلكت امرأة لوط؟ وما وجه موافقتها لقومها؟\nقُلِ ٱلۡحَمۡدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصۡطَفَىٰٓۗ ءَآللَّهُ خَيۡرٌ أَمَّا يُشۡرِكُونَ ٥٩\nأَمر بأَن يُتبعه بِالسلامِ علَى الرسلِ؛ الَّذين سبقُوه قَدَرًا لقَدرِ ما تجَشموه في نشرِ الدينِ الحق. ابن عاشور:٢٠/٦.\nلماذا جاء الأمر بالسلام على الرسل بعد حمد الله تعالى؟\nأَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارٗا وَجَعَلَ خِلَٰلَهَآ أَنۡهَٰرٗا وَجَعَلَ لَهَا رَوَٰسِيَ وَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٦١\nوهذا تدبير عجيب، ولا يُدرك تمام هذا الصنع العجيب إلا عند العلم بأن هذه الأرض سابحة في الهواء، متحركة في كل لحظة، وهي مع ذلك قارّة فيما يبدو لسكانها؛ فهذا تدبير أعجب، وفيه مع ذلك رحمة ونعمة، ولولا قرارها لكان الناس عليها متزلزلين مضطربين، ولكانت أشغالهم مُعنتة لهم. ابن عاشور:٢٠/١٣.\nكيف ندرك عظمة تدبير الله تعالى للأرض؟\nوَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٦١\n﴿وَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ﴾ البحر المالح والبحر العَذب (حاجزًا) يمنع من اختلاطهما فتفوت المنفعة المقصودة من كل منهما. السعدي:٦٠٨.\nلماذا جعل بين البحرين حاجزًا؟\nأَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قَلِيلٗا مَّا تَذَكَّرُونَ ٦٢\nالوجه في إجابة المضطر أن ذلك الاضطرار الحاصل له يتسبب عنه الإخلاص وقطع النظر عما سوى الله، وقد أخبر الله سبحانه بأنه يجيب دعاء المخلصين له الدين وإن كانوا كافرين؛ فقال: ﴿حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ﴾ [يونس: ٢٢]، وقال: ﴿فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ﴾ [العنكبوت: ٦٥]؛ فأجابهم عند ضرورتهم وإخلاصهم مع علمه بأنهم سيعودون إلى شركهم. الشوكاني:٤/١٦٩\nما سبب إجابة الله دعاء المضطر وإن كان كافرًا ؟\nأَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قَلِيلٗا مَّا تَذَكَّرُونَ ٦٢\nضمن الله تعالى إجابة المضطر إذا دعاه، وأخبر بذلك عن نفسه؛ والسبب في ذلك أن الضرورة إليه باللَّجاء ينشأ عن الإخلاص وقطع القلب عما سواه، وللإخلاص عنده سبحانه موقع وذمة، وُجِد من مؤمن أو كافر، طائع أو فاجر. القرطبي:١٦/١٩٣.\nبيّن ثمرة إخلاص الدعاء لله -سبحانه وتعالى-."],[383,"§النمل\nwords\nوَمَا يَشعُرُونمَا يَعلَمُونَ.\nأَيَّانَمَتَى.\nادَّارَكَتَكَامَلَ أَوِ انتَهَى عِلمُهُم وَعَجَزَ عَن مَعرِفَةِ وَقتِهَا.\nعَمُونَعَمِيَت بَصَائِرُهُم عَنهَا.\nأَسَاطِيرُ الأَوَّلِينَمَا سَطَّرَ القُدَمَاءُ مِنَ الأَكَاذِيبِ.\nرَدِفَ لَكُماقتَرَبَ لَكُم.\nتُكِنُّتُخفِي.\ndeeds\nانصح من يبحثون عن الغيب من خلال النجوم أو المشعوذين.\nاقرأ وتأمل في مصارع الظالمين.\nتذكر خمسًا من أكبر نعم الله عليك، ثم اشكر الله تعالى عليها.\nguid\nعلم الغيب خاص بالله تعالى، فمن ادعى أنه يعلم غيبًا فقد كذب.\nعدم التصديق باليوم الآخر يجعل العبد متجرئًا على المعاصي.\nاتباع هدي القرآن فيه العصمة من الاختلاف والفرقة.\nrefl\nقُل لَّا يَعۡلَمُ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلۡغَيۡبَ إِلَّا ٱللَّهُۚ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ ٦٥\nلما أبطلت الآيات السابقة إلهية أصنام المشركين بالأدلة المتظاهرة فانقطع دابر عقيدة الإشراك، ثُني عنانُ الإبطال إلى أثر من آثار الشرك؛ وهو ادّعاء علم الغيب بالكهانة وإخبار الجن. ابن عاشور:٢٠/١٩.\nأبطلت الآيات الكريمة أثرًا من آثار الشرك، فما هو؟\nبَلِ ٱدَّٰرَكَ عِلۡمُهُمۡ فِي ٱلۡأٓخِرَةِۚ بَلۡ هُمۡ فِي شَكّٖ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ ٦٦\nفانتقل في الإخبار عن أحوال هؤلاء المكذبين بالإخبار أنهم لا يدرون متى وقت الآخرة، ثم الإخبار بضعف علمهم فيها، ثم الإخبار بأنه شك، ثم الإخبار بأنه عمىً، ثم الإخبار بإنكارهم لذلك واستبعادهم وقوعه؛ أي: وبسبب هذه الأحوال ترحَّل خوف الآخرة من قلوبهم، فأقدموا على معاصي الله، وسهل عليهم تكذيب الحق، والتصديق بالباطل، واستحلوا الشهوات على القيام بالعبادات؛ فخسروا دنياهم وأخراهم. السعدي:٦٠٩.\nما السبب الذي جعل الكفار مقدمين على أنواع المعاصي، ومتجرئين عليها؟\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ ٦٩\nثم وعظهم تعالى بحال مَنْ كذب من الأمم، فأمر نبيه أن يأمرهم بالسير والتطلع على حال مجرمي الأمم، وبالحذر أن يصيبهم مثل ما أصاب أولئك. ابن عطية:٤/٢٦٩.\nما الفائدة من قراءة سير المجرمين وتاريخهم؟\nوَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُن فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ ٧٠\nكانت الرحمة غالبة على النبي -صلى الله عليه وسلم- والشفقة على الأمة من خلاله؛ فلمّا أُنذر المكذبون بهذا الوعيد، تحركت الشفقة في نفس الرسول -عليه الصلاة والسلام- فربط الله على قلبه بهذا التشجيع أن لا يحزن عليهم إذا أصابهم ما أنذروا به. ابن عاشور:٢٠/٢٦.\nكيف دلت الآية على رحمته -صلى الله عليه وسلم- بالخلق؟\nقُلۡ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعۡضُ ٱلَّذِي تَسۡتَعۡجِلُونَ ٧٢ وَإِنَّ رَبَّكَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ ٧٣\nوهذا خبر خاص بالنبي -صلى الله عليه وسلم- تنبيهًا على أن تأخير الوعيد أثر من آثار رحمة الله؛ لأن أزمنة التأخير أزمنة إمهال، فهم فيها بنعمة. ابن عاشور:٢٠/٢٨.\nتأخير العذاب أثر من آثار رحمة الله تعالى، بيّن ذلك.\nوَإِنَّ رَبَّكَ لَيَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ ٧٤\nوفي الآية إيذان بأن لهم قبائح غير ما حكي عنهم. وتقديم الاكتنان ليظهر المراد من استواء الخفي والظاهر في علمه -جل وعلا-، أو لأن مضمرات الصدور سبب لما يظهر على الجوارح. الألوسي:١٠/٢٢٨.\nما فائدة تقديم علم ما تكنه صدورهم على ما يعلنون؟ وكيف تستدل من الآية على أهمية أعمال القلوب؟\nإِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَقُصُّ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَكۡثَرَ ٱلَّذِي هُمۡ فِيهِ يَخۡتَلِفُونَ ٧٦\nوالمعنى: إن هذا القرآن يبين لهم ما اختلفوا فيه لو أخذوا به. القرطبي:١٦/٢٠٤.\nإذا اختلفنا في أمر من الأمور فأين نجد المخرج؟"],[384,"§النمل\nwords\nوَلَّوا مُدبِرِينَأَعرَضُوا عَنكَ.\nفَوجًاجَمَاعَةً.\nيُوزَعُونَيُدفَعُونَ أَو يُحبَسُ أَوَّلُ المُكَذِّبِينَ مِن كُلِّ أُمَّةٍ عَلَى آخِرِهِم؛ لِيَجتَمِعُوا، ثُمَّ يُسَاقُونَ إِلَى الحِسَابِ.\nدَاخِرِينَصَاغِرِينَ أَذِلاَّءَ.\nجَامِدَةًوَاقِفَةً مُستَقِرَّةً.\nتَمُرُّتَسِيرُ.\ndeeds\nادع الله أن يجعل القرآن الكريم حجة لك، ورحمة عليك.\nاستمع إلى محاضرة أو موعظة، ثم اعمل بما سمعت.\nنم ليلة مبكرًا ثم نم ليلة أخرى متأخرًا، وانظر الفرق بينهما على نفسيتك وصحتك وأعمالك وعبادتك.\nguid\nهداية الناس ورحمتهم من مقاصد القرآن الكريم.\nكل خلاف بين الناس اليوم سيحكم الله تعالى بين أهله يوم القيامة بحكمه العادل.\nالواجب على المسلم وطالب العلم أن يتوقف عن أي مسألة ليس له فيها علم حتى ينكشف له الحق؛ فلا يتكلم إلا بعلم.\nrefl\nوَإِنَّهُۥ لَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ٧٧\nوأما كونه رحمة لهم؛ فلأنهم لمَّا اهتدوا به قد نالوا الفوز في الدنيا؛ بصلاح نفوسهم، واستقامة أعمالهم، واجتماع كلمتهم، وفي الآخرة؛ بالفوز بالجنة. ابن عاشور:٢٠/٣١.\nكيف كان القرآن الكريم رحمة للمؤمنين؟\nوَإِنَّهُۥ لَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ٧٧\nوتخصيص المؤمنين بالذكر مع أنه رحمة للعالمين؛ لأنهم المنتفعون به. الألوسي:١٠/٢٢٩.\nلماذا خصَّ المؤمنين بالذكر مع أنه رحمة للعالم كله؟\nفَتَوَكَّلۡ عَلَى ٱللَّهِۖ إِنَّكَ عَلَى ٱلۡحَقِّ ٱلۡمُبِينِ ٧٩\n﴿إِنَّكَ عَلَى ٱلۡحَقِّ ٱلۡمُبِينِ﴾: الواضح. والذي على الحق -يدعو إليه ويقوم بنصرته- أحق من غيره بالتوكل؛ فإنه يسعى في أمر مجزوم به، معلوم صدقه، لا شك فيه ولا مرية. السعدي:٦٠٩.\nما علاقة التوكل بكون النبي -صلى الله عليه وسلم- على الحق المبين؟\nإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوۡاْ مُدۡبِرِينَ ٨٠\n﴿إِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ﴾ يعني: الكفار؛ لتركهم التدبر فهم كالموتى؛ لا حس لهم، ولا عقل... ﴿وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ﴾ يعني: الكفار الذين هم بمنزلة الصم عن قبول المواعظ، فإذا دُعُوا إلى الخير أعرضوا وولَّوا؛ كأنهم لا يسمعون. القرطبي:١٦/٢٠٥.\nلِمَ شبه هؤلاء بالموتى وبالصم؟\nوَوَقَعَ ٱلۡقَوۡلُ عَلَيۡهِم بِمَا ظَلَمُواْ فَهُمۡ لَا يَنطِقُونَ ٨٥\nقال قتادة: \"كيف ينطقون ولا حجة لهم؟\". البغوي:٣/٤١٨.\nلماذا سكتوا عن النطق؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٨٦\nأي: قضيت بأن إيمانهم لا يزال يتجدد، فهم كل يوم في علو وارتفاع. البقاعي:١٤/٢٢٢.\nما فائدة التعبير بالفعل المضارع: (يؤمنون)؟\nصُنۡعَ ٱللَّهِ ٱلَّذِيٓ أَتۡقَنَ كُلَّ شَيۡءٍۚ إِنَّهُۥ خَبِيرُۢ بِمَا تَفۡعَلُونَ ٨٨\nكل ما خلقه الله فله فيه حكمة؛ كما قال: ﴿صُنۡعَ ٱللَّهِ ٱلَّذِيٓ أَتۡقَنَ كُلَّ شَيۡءٍۚ﴾، وقال: ﴿ٱلَّذِيٓ أَحۡسَنَ كُلَّ شَيۡءٍ خَلَقَهُۥ﴾ [السجدة: ٧]. وهو سبحانه غني عن العالمين؛ فالحكمة تتضمن شيئين؛ أحدهما: حكمة تعود إليه؛ يحبها ويرضاها. والثاني: إلى عباده، هي نعمة عليهم يفرحون بها ويلتذون بها. ابن تيمية: ٥/٦٨.\nكل ما خلقه الله تعالى فيه حكمة، بين ما الذي تتضمنه حكمته سبحانه."],[385,"§النمل ، القصص\nwords\nبِالحَسَنَةِبِالتَّوحِيدِ، وَالإِيمَانِ، وَالعِبَادَةِ.\nبِالسَّيِّئَةِبِالشِّركِ وَالكُفرِ.\nحَرَّمَهَاجَعَلَهَا حَرَامًا؛ فَلاَ يُسفَكُ فِيهَا دَمٌ، أَو يُصَادُ صَيدٌ، أَو يُقطَعُ شَجَرٌ.\nعَلاَتَكَبَّرَ، وَطَغَى.\nشِيَعًاطَوَائِفَ مُتَفَرِّقَةً.\nنَمُنَّنَتَفَضَّلَ.\ndeeds\nاعمل عملًا صالحًا، وسل الله تعالى أن يضاعف لك أجره.\nاقرأ سورة من سور القرآن الكريم بتدبر وتفهّم.\nقل: \"اللهم أرني الحق حقًا، وارزقني اتباعه، وأرني الباطل باطلًا، وارزقني اجتنابه\".\nguid\nعلى قدر عملك للحسنات يكون أمنك من الفزع يوم القيامة.\nإذا أراد الله الهداية للعبد فقد يكون سبب هدايته مجرد سماعه لتلاوة القرآن الكريم.\nمن سنن الله سبحانه أن يهلك الظالمين إذا تعالوا على المصلحين، أو فرقوا كلمتهم، أو سعوا في إضعافهم أو قتلهم.\nrefl\nمَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَا وَهُم مِّن فَزَعٖ يَوۡمَئِذٍ ءَامِنُونَ ٨٩\n﴿فَلَهُۥ خَيۡرٌ مِّنۡهَا﴾: للتفضيل؛ أي: ثواب الله خير من عمل العبد وقوله وذكره، وكذلك رضوان الله خير للعبد من فعل العبد. وقيل: ويرجع هذا إلى الإضعاف؛ فإن الله تعالى يعطيه بالواحدة عشرا، وبالإيمان في مدة يسيرة الثواب الأبدي. القرطبي ١٦/٢٢٤.\nما معنى قوله تعالى في الآية: ﴿فَلَهُۥ خَيۡرٌ مِّنۡهَا﴾؟\nوَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ\n﴿وَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَۖ﴾ أي: أواظب على قراءته على الناس بطريق تكرير الدعوة وتثنيته الإرشاد؛ لكفايته في الهداية إلى طريق الرشاد، وقيل: أي أواظب على قراءته لينكشف لي حقائقه الرائقة المخزونة في تضاعيفه شيئًا فشيئا. الألوسي:١٠/٢٤٨.\nما أثر المواظبة على قراءة القرآن الكريم؟\nوَمَن ضَلَّ فَقُلۡ إِنَّمَآ أَنَا۠ مِنَ ٱلۡمُنذِرِينَ ٩٢\nأي: لي أسوة بالرسل الذين أنذروا قومهم، وقاموا بما عليهم من أداء الرسالة إليهم، وخلصوا من عهدتهم، وحساب أممهم على الله تعالى. ابن كثير:٣/٣٦٦.\nما واجب المنذرين تجاه الضالين؟\nنَتۡلُواْ عَلَيۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمٖ يُؤۡمِنُونَ ٣\nفإليهم يساق الخطاب، ويوجه الكلام؛ حيث إن معهم من الإيمان ما يقبلون به على تدبر ذلك، وتَلَقِّيه بالقبول، والاهتداء بمواقع العبر، ويزدادون إيمانًا ويقينًا وخيرًا إلى خيرهم، وأمَّا من عداهم فلا يستفيدون منه إلا إقامة الحجة عليهم، وصانه الله عنهم، وجعل بينهم وبينه حجابًا أن يفقهوه. السعدي:٦١١.\nلماذا خُصَّت القصة بالقوم المؤمنين؟\nإِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ\nوصورت عظمة فرعون في الدنيا بقوله: ﴿عَلَا فِي ٱلۡأَرۡضِ﴾ لتكون العبرة بهلاكه بعد ذلك العلو أكبر العبر. ابن عاشور:٢٠/٦٦.\nلماذا وصفت عظمة فرعون وتكبره بقوله تعالى: ﴿عَلَا فِي ٱلۡأَرۡضِ﴾؟\nإِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا\n(شيعًا) أي: فرقًا يتبع كل فرقة شيئًا وتنصره، والكل تحت قهره وطوع أمره؛ قد صاروا معه كالشياع -وهو دِقّ الحطب-؛ فرق بينهم لئلَّا يتمالؤوا عليه، فلا يصل إلى ما يريده منهم، فافترقت كلمتهم، فلم يحم بعضهم لبعض، فتخاذلوا، فسفُل أمرهم. البقاعي:١٤/٢٤٠.\nمن أهداف الأعداء دائمًا تفريق الصف، ما أثر التفرق على قوة الأمة؟\nيُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ ٤\nوذلك لأن الكهنة قالوا له: إن مولودًا يولد في بني إسرائيل يذهب ملكك على يديه، أو قال المنجمون له ذلك، أو رأى رؤيا فعبرت كذلك. قال الزجاج: \"العجب من حمقه! لم يدر أن الكاهن إن صدق فالقتل لا ينفع، وإن كذب فلا معنى للقتل\". القرطبي:١٦/٢٣٠.\nبيّن ما بلغه حمق فرعون."],[386,"§القصص\nwords\nاليَمِّالنَّهرِ، وَهُوَ نَهرُ النِّيلِ.\nقُرَّةُ عَينٍ لِيمَصدَرُ سُرُورٍ لِي.\nفَارِغًاخَالِيًا مِن كُلِّ شَيءٍ إِلاَّ هَمَّ مُوسَى -عليه السلام-.\nلَتُبدِي بِهِفَتُصَرِّحُ بِأَنَّهُ ابنُهَا.\nعَن جُنُبٍعَن بُعدٍ.\nيَكفُلُونَهُ لَكُميَقُومُونَ بِتَربِيَتِهِ وَإِرضَاعِهِ.\ndeeds\nوجه رسالة إلى أسرة ظلم أحد أفرادها وبشرهم بهذه الآية.\nسل الله تعالى أن يجعل زوجتك وذريتك قرة عين لك.\nادع الله تعالى أن يربط على قلبك، ويثبتك في السراء والضراء.\nguid\nالتمكين في الأرض يحتاج إلى صبر، وإعداد، وبذل جهد.\nقد تأتي المنح مع المحن؛ فإن الله تعالى يَعِدُ أم موسى في لحظة كربتها بالفرج مع فضل عظيم، وهو جعل ابنها نبيًّا مرسلًا.\nالصبر عند المصائب منة من الله تعالى، فاسأل الله إياها.\nrefl\nوَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ ٧\nبيَّن أنه يلهم المؤمنين الإيمان وما ينفعهم، وذلك إيحاء إليهم وإن لم يكونوا أنبياء. ابن تيمية:٥/٧٠.\nبينت الآية الكريمة فضل الله تعالى على المؤمنين، بين ذلك؟\nوَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إلى قوله تعالى وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ\nإن العبد ولو عرف أن القضاء والقدر ووعد الله نافذ لا بد منه فإنه لا يهمل فعل الأسباب التي أُمِرَ بها، ولا يكون ذلك منافيًا لإيمانه بخبر الله؛ فإن الله قد وعد أم موسى أن يرده عليها، ومع ذلك اجتهدت في رده، وأرسلت أخته لتقصه وتطلبه. السعدي:٦١٩.\nإرسال أم موسى أخته لتنظر ماذا حصل في أمره، هل ينافي الإيمان بوعد الله -سبحانه وتعالى-؟\nوَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ ٧\nوإنَّما أمرها الله بإرضاعه لتقوى بُنيته بلبان أمه؛ فإنه أسعد بالطفل في أول عمره من لبان غيرها، وليكون له من الرضاعة الأخيرة -قبل إلقائه في اليمّ -قوت يشد بنيته فيما بين قذفه في اليم وبين التقاط آل فرعون إياه، وإيصاله إلى بيت فرعون. ابن عاشور:٢٠/٧٣.\nلماذا أمرت أم موسى بإرضاعه قبل إلقائه في البحر؟\nوَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ ٩\nوجود الصالحين من بين المفسدين يخفف من لأواء فساد المفسدين؛ فإن وجود امرأة فرعون كان سببًا في صد فرعون عن قتل الطفل؛ مع أنه تحقق أنه إسرائيلي. ابن عاشور:٢٠/٨٦.\nوجود الصالحين بين المفسدين يخفف من الفساد، بين ذلك.\nعَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا\nفقَدَّر الله تعالى أنه نفع امرأة فرعون التي قالت تلك المقالة؛ فإنه لمَّا صار قرة عين لها، وأحبته حبًا شديدًا، فلم يزل لها بمنزلة الولد الشفيق حتى كبر، ونبأه الله وأرسله، فبادرت إلى الإسلام والإيمان به، رضي الله عنها وأرضاها. السعدي:٦١٢.\nهل انتفعت امرأة فرعون من شفقتها على موسى؟\nوَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ١٠\nفإن العبد إذا أصابته مصيبة فصبر وثبت ازداد بذلك إيمانه، ودل ذلك على أن استمرار الجزع مع العبد دليل على ضعف إيمانه. السعدي:٦١٣.\nما علاقة الجزع بزيادة الإيمان ونقصانه؟\nوَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ١٠\nقيل: فارغًا من كل شيء إلا من ذكر موسى. ابن تيمية:١٠/٢١٩.\nحب الأم لأولادها عظيم، بين ذلك من خلال الآية."],[387,"§القصص\nwords\nمِن شِيعَتِهِمِن قَومِ مُوسَى -عليه السلام-، وَهُم بَنُو إِسرَائِيلَ.\nفَوَكَزَهُضَرَبَهُ بِجُمعِ كَفِّهِ.\nيَتَرَقَّبُيَتَوَقَّعُ المَكرُوهَ.\nيَستَصرِخُهُيَطلُبُ مِنهُ النَّصرَ.\nلَغَوِيٌّكَثِيرُ الغَوَايَةِ، ضَالٌّ عَنِ الرُّشدِ.\ndeeds\nأصلح بين اثنين متخاصمين.\nتذكر ذنبًا فعلته، واستغفر الله، وقل: \"رب إني ظلمت نفسي فاغفر لي\".\nدافع عن أحد الصالحين بالذب عنه فيما يكتب في الصحف، أو الإنترنت، أو الرسائل.\nguid\nأحسن في عبادتك يعطك الله حكمة و علمًا.\nاحذر الشيطان؛ فإنه عدوٌ لبني آدم، مُضِلٌّ لهم.\nمن الإحسان: المبادرة في تقديم الخير للناس، وبذل النصيحة لهم.\nrefl\nوَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ١٤\n﴿وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ﴾: في عبادة الله، المحسنين لخلق الله؛ نعطيهم علمًا وحكمًا بحسب إحسانهم، ودلَّ هذا على كمال إحسان موسى -عليه السلام-. السعدي:٦١٣.\nدلَّت الآية على عظيم جزاء الإحسان، بَيِّن وجه ذلك.\nقَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ ١٥\nفي هذا دليل على أن الأصل في النفس الإنسانية هو الخير، وأنه الفطرة، وأن الانحراف عنها يحتاج إلى سبب غير فطري؛ وهو تخلل نزغ الشيطان في النفس. ابن عاشور:٢٠/٩٠.\nما الأصل في النفس الإنسانية من خلال الآية الكريمة؟\nوَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ ١٥\n﴿فَقَضَىٰ عَلَيۡهِۖ﴾ معناه: قتله مجهزًا، وكان موسى -عليه السلام- لم يُرِد قتل القبطي، لكن وافقت وكزته الأجل وكان عنها موته فندم، ورأى أن ذلك من نزغ الشيطان في يده، وأن الغضب الذي اقترنت به تلك الوكزة كان من الشيطان ومن همزه، ونص هو -عليه السلام- على ذلك، وبهذا الوجه جعله من عمله، وكان فضل قوة موسى ربما أفرط في وقت غضبه بأكثر مما يقصد. ابن عطية:٤/٢٨٠.\nما وجه إضافة موسى -عليه الصلاة والسلام- قتله للقبطي إلى الشيطان؛ مع أنه هو الفاعل؟\nقَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ\nفاعترف بظلمه نفسه فيما كان من جناية على غيره لم يؤمر بها. ابن تيمية: ٥/٧١.\nالاعتراف بالحق صفة الأنبياء، بين ذلك.\nقَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ١٦\nثم اعترف واستغفر؛ فغفر الله له. فإن قيل: كيف استغفر من القتل وكان المقتول كافرًا؟ فالجواب: أنه لم يؤذن له في قتله، ولذلك يقول يوم القيامة: إني قتلت نفسًا لم أومر بقتلها. ابن جزي:٢/١٤١.\nكيف استغفر موسى -عليه السلام- من قتل كافر؟\nقَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ١٦\nندم موسى -عليه السلام- على ذلك الوكز الذي كان فيه ذهاب النفس، فحمله ندمه على الخضوع لربه، والاستغفار من ذنبه. قال قتادة: \"عرف والله المخرج\". فاستغفر، ثم لم يزل يعدد ذلك على نفسه مع علمه بأنه قد غُفر له، حتى أنه في القيامة يقول: إني قتلت نفسًا لم أومر بقتلها. وإنَّما عدده على نفسه ذنبًا، وقال: ﴿ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي﴾ من أجل أنه لا ينبغي لنبي أن يقتل حتى يؤمر، وأيضًا فإن الأنبياء يشفقون مما لا يشفق منه غيرهم. القرطبي:١٦/٢٤٧-٢٤٨.\nلماذا اعتبر موسى -عليه السلام- نفسه مذنبًا بقتل القبطي؟\nقَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ ظَهِيرٗا لِّلۡمُجۡرِمِينَ ١٧\nالظهير: المعين، والباء سببية، والمعنى: بسبب إنعامك عليّ لا أكون ظهيرًا للمجرمين؛ فهي معاهدة عاهد موسى عليها ربه. ابن جزي:٢/١٤٠.\nما الذي يجب على المؤمن فعله إذا وقع منه ذنب ثم رأى نعم الله عليه بالستر والإحسان؟"],[388,"§القصص\nwords\nتِلقَاءَ مَديَنَجِهَتَهَا.\nسَوَاءَ السَّبِيلِالطَّرِيقَ الأَحسَنَ إِلَى مَديَنَ.\nتَذُودَانِتَحبِسَانِ غَنَمَهُمَا عَنِ المَاءِ.\nمَا خَطبُكُمَامَا شَأنُكُمَا؟\nيُصدِرَ الرِّعَاءُيَنصَرِفَ الرُّعَاةُ بِأَغنَامِهِم عَنِ المَاءِ.\nتَأجُرَنِيتَكُونَ أَجِيرًا لِي فِي رَعيِ مَاشِيَتِي.\nحِجَجٍسِنِينَ.\ndeeds\nساعد أحد الضعفاء بتقديم يد العون له.\nأرسل رسالة تنصح من تتكشف بستر نفسها، وأن الحياء سنة المؤمنات منذ القدم.\nكافئ شخصًا أحسن إليك؛ فإن هذا من دأب الصالحين.\nguid\nفضل الحياء للنساء، وشرف المؤمنات اللائي يتعففن عن الاختلاط بالرجال.\nرعاية الضعفاء والقيام على مصالحهم من أخلاق الأنبياء وشيَمهم.\nمن أسباب إجابة الدعاء تضرع العبد، وإظهاره ذله ومسكنته، كما قال موسى -عليه السلام-.\nrefl\nقَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ ٢٣\n﴿قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ﴾: امرأتان لا نستطيع أن نزاحم الرجال، ﴿وَأَبُونَا شَيۡخٌ كَبِيرٌ﴾ لا يقدر أن يمس ذلك من نفسه، ولا يسقي ماشيته، فنحن ننتظر الناس حتى إذا فرغوا أسقينا، ثم انصرفنا. الطبري:١٩/٥٥٤.\nدلت الآية على أن منع الاختلاط بين الجنسين من سنن الأنبياء والصالحين، وضح ذلك.\nفَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ ٢٤\nفأول ذلك إيتاء الحكمة والعلم، ومن الخير: إنجاؤه من القتل، وتربيته الكاملة في بذخة الملك وعزته، وحفظه من أن تتسرب إليه عقائد العائلة التي ربي فيها؛ فكان منتفعًا بمنافعها، مجنبًا رذائلها وأضرارها. ومن الخير: أن جعل نصر قومه على يده، وأن أنجاه من القتل الثاني ظلمًا، وأن هداه إلى منجى من الأرض، ويسر له التعرف ببيت نبوءة. ابن عاشور:٢٠/ ١٠٢.\nاذكر ثلاثة من أوجه الخير التي أكرم الله به عبده موسى.\nفَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ\nولما كان الحياء كأنه مركب لها وهي متمكنة منه، مالكة لزمامه، عبر بأداة الاستعلاء، فقال: ﴿عَلَى ٱسۡتِحۡيَآءٍ﴾ أي: حياء موجود منها؛ لأنها كلفت الإتيان إلى رجل أجنبي؛ تكلمه، وتماشيه. البقاعي:١٤/٢٦٨.\nالحياء سبب للزواج من الرجل الصالح، وضح هذا من خلال الآية.\nقَالَتۡ إِحۡدَىٰهُمَا يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ ٢٦\n(استأجره) أي: اجعله أجيرًا لك، ﴿إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ﴾: هذا الكلام حكمة جامعة بليغة. روي أن أباها قال لها: من أين عرفت قوته وأمانته؟ قالت: أما قوته ففي رفعه الحجر عن فم البئر، وأمَّا أمانته فإنه لم ينظر إليّ. ابن جزي:٢/١٤٣.\nفي الآية مشروعية تقديم النصح لمن بيده الأمر، بيّن ذلك.\nإِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ ٢٦\nهذان الوصفان ينبغي اعتبارهما في كل من يتولى للإنسان عملًا بإجارة أو غيرها؛ فإن الخلل لا يكون إلا بفقدهما أو فقد إحداهما. وأمَّا اجتماعهما فإن العمل يتم ويكمل. السعدي:٦١٤.\nكيف نستنبط من الآية الصفات المثلى فيمن يتولى شؤون العامة؟\nوَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ ٢٧\nفرغَّبه في سهولة العمل، وفي حسن المعاملة، وهذا يدل على أن الرجل الصالح ينبغي له أن يحسن خلقه مهما أمكنه. السعدي:٦١٥.\nكيف تدل الآية على الواجب في أخلاق أصحاب الأعمال وأربابها؟\nسَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ ٢٧\nقصد بذلك تعريف خُلُقه لصاحبه، وليس هذا من تزكية النفس المنهي عنه؛ لأن المنهي عنه ما قصد به قائله الفخر والتمدح، فأما ما كان لغرض في الدين أو المعاملة؛ فذلك حاصل لداع حسن. ابن عاشور:٢٠/١٠٩.\nهل في قول شعيب: ﴿سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ﴾ تزكية لنفسه؟"],[389,"§القصص\nwords\nآنَسَأَبصَرَ.\nجَذوَةٍشُعلَةٍ مِنَ النَّارِ.\nتَصطَلُونَتَستَدفِئُونَ.\nشَاطِئِجَانِبِ.\nفَذَانِكَهَاتَانِ.\nرِدءًاعَونًا.\nسَنَشُدُّ عَضُدَكَسَنُقَوِّيكَ، وَنُعِينُكَ.\ndeeds\nاشكُ همك وخوفك إلى الله تعالى وحده، متأسيًا بنبي الله موسى في شكواه إلى ربه.\nساعد أحد الدعاة في أمر يحتاجه.\nاستعن بمن يعينك على القيام بدعوتك ممن يملك المواصفات المناسبة.\nguid\nالأنبياء أوفياء؛ فموسى قضى أوفى الأجلين وأتمه؛ وهو العشر.\nمن صفات الصالحين: السعي في طلب الرزق، والاجتهاد في حل المشكلات الدنيوية؛ بحكمة وصبر.\nاحرص على استحضار الدليل والمثال المناسب في دعوتك.\nrefl\nفَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ٣٠\nوصف ﴿رَبِّ ٱلۡعَٰلَمِينَ﴾ يدل على أن جميع الخلائق مسخرة له؛ ليثبت بذلك قلب موسى من هول تلقي الرسالة. ابن عاشور:٢٠/١١٢.\nما دلالة وصف ﴿رَبِّ ٱلۡعَٰلَمِينَ﴾ في الآية الكريمة؟\nوَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡأٓمِنِينَ ٣١\nيبقى احتمال؛ وهو أنه قد يقبل وهو غير خائف، ولكن لا تحصل له الوقاية والأمن من المكروه، فقال: ﴿إِنَّكَ مِنَ ٱلۡأٓمِنِينَ﴾ فحينئذ اندفع المحذور من جميع الوجوه؛ فأقبل موسى -عليه السلام- غير خائف ولا مرعوب، بل مطمئنًا، واثقًا بخبر ربه، قد ازداد إيمانه، وتم يقينه؛ فهذه آية أراه الله إياها قبل ذهابه إلى فرعون ليكون على يقين تام، فيكون أجرأ له، وأقوى وأصلب. السعدي:٦١٥.\nخوف القلوب وأمنها بيد الله سبحانه، وضح ذلك من الآية.\nوَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ٣٤\nوإنَّما عيّنه ولم يسأل مؤيدًا ما؛ لعلمه بأمانته، وإخلاصه لله ولأخيه، وعلمه بفصاحة لسانه. ابن عاشور:٢٠/١١٦.\nمن سنن الأنبياء الحرص على الرفيق المصاحب في الدعوة؛ صاحب الصفات المناسبة، بَيِّن هذا من خلال الآية.\nوَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ٣٤\n﴿فَأَرۡسِلۡهُ مَعِيَ رِدۡءًا﴾ أي: معاونًا ومساعدًا، (يصدقني) فإنه مع تضافر الأخبار يقوى الحق. فأجابه الله إلى سؤاله فقال: ﴿سَنَشُدُّ عَضُدَكَ بِأَخِيكَ﴾ أي: نعاونك به ونقويك. السعدي:٦١٥.\nمن كان صادقًا في حمل همّ الدعوة فإنه يسعى لإكمال نقصه بوسائل أخرى، وضح ذلك من الآية.\nقَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ\nقال بعض السلف: ليس أحدٌ أعظم منة على أخيه من موسى على هارون -عليهما السلام-؛ فإنه شفع فيه حتى جعله الله نبيًا ورسولًا معه إلى فرعون وملئه. ابن كثير:٣/٣٧٥.\nلموسى على هارون -عليهما السلام- منة عظيمة، بَيِّنها.\nوَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ ٣٥\n﴿أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ﴾: وهذا وعد لموسى في ذلك الوقت، وهو وحده فريد، وقد رجع إلى بلده بعد ما كان شريدًا، فلم تزل الأحوال تتطور، والأمور تنتقل، حتى أنجز الله له موعوده، ومكنه من العباد والبلاد، وصار له ولأتباعه، الغلبة والظهور. السعدي:٦١٥.\nما فائدة هذه الآية لموسى -عليه السلام- قبل بعثه لفرعون؟\nقَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ ٣٥\nومحل العبرة من هذا الجزء من القصة: التنبيه إلى أن الرسالة فيض من الله على من اصطفاه من عباده، وأن رسالة محمد -صلى الله عليه وسلم- كرسالة موسى: جاءته بغتة؛ فنودي محمد في غار جبل حراء كما نودي موسى في جانب جبل الطور، وأنه اعتراه من الخوف مثل ما اعترى موسى، وأن الله ثبته كما ثبت موسى، وأن الله يكفيه أعداءه كما كفى موسى أعداءه. ابن عاشور:٢٠/١١٨.\nفي الآية إشارة وتلميح بأن الله سيثبت وينصر نبيه محمدًا -صلى الله عليه وسلم-، وضح ذلك."],[390,"§القصص\nwords\nمُفتَرىًمُختَلَقٌ، تَنسُبُهُ إِلَى اللهِ كَذِبًا.\nعَاقِبَةُ الدَّارِالنِّهَايَةُ المَحمُودَةُ فِي الآخِرَةِ.\nصَرحًابِنَاءً عَالِيًا.\nفَنَبَذنَاهُم فِي اليَمِّفَأَلقَينَاهُم وَأَغرَقنَاهُم فِي البَحرِ.\nأَئِمَّةًقَادَةً إِلَى النَّارِ.\nوَأَتبَعنَاهُمأَلحَقنَاهُم.\nالمَقبُوحِينَالمُبعَدِينَ المُستَقذَرَةِ أَفعَالُهُم.\nبَصَائِرَ لِلنَّاسِنُورًا لِقُلُوبِهِم يُبصِرُونَ بِهِ الحَقَائِقَ.\ndeeds\nاستعذ بالله من الاستكبار عن الحق.\nأرسل رسالة تحذر فيها من يقتدى به في الشر أن عليه وزره ووزر من اقتدى به.\nسل الله تعالى أن تكون إمامًا في الخير، واستعذ به أن تكون إمامًا في الشر.\nguid\nالمؤمن واثق من وعد الله أهل طاعته بالعاقبة الحميدة.\nاحذر أن تكون ظالمًا؛ فعاقبة الظالمين إلى الخسارة.\nعاقبة الظلمة الدمار والهلاك.\nrefl\nفَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا سِحۡرٞ مُّفۡتَرٗى وَمَا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ٣٦\n﴿وَمَا سَمِعۡنَا بِهَٰذَا﴾ أي: الذي تقوله من الرسالة عن الله. ﴿فِيٓ ءَابَآئِنَا﴾: وأشاروا إلى البدعة التي قد أضلت أكثر الخلق؛ وهي تحكيم عوائد التقليد؛ ولا سيما عند تقادمها. البقاعي:١٤/٢٩٢.\nما أكثر حجة يرددها المبتدعة في بدعتهم؟\nوَقَالَ فِرۡعَوۡنُ يَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ ٣٨\nولكن العجب من هؤلاء الملأ الذين يزعمون أنهم كبار... كيف لعب هذا الرجل بعقولهم، واستخف أحلامهم؟! وهذا لفسقهم الذي صار صفة راسخة فيهم، فسد دينهم، ثم تبع ذلك فساد عقولهم. السعدي:٦١٦.\nكيف فسدت عقول قوم فرعون؟\nفَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ ٤٠\nفانظر يا محمد بعين قلبك: كيف كان أمر هؤلاء الذين ظلموا أنفسهم فكفروا بربهم، وردوا على رسوله نصيحته؛ ألم نهلكهم فنورث ديارهم وأموالهم أولياءنا؟! الطبري:١٩/٥٨٢.\nبيّن كيف أمر الله نبيه -عليه الصلاة والسلام- بأن ينظر إلى عاقبة إهلاك فرعون وجنوده ولم يكن معهم في زمنهم؟\nوَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ ٤١\n﴿أَئِمَّةً يَدۡعُونَ إِلَى ٱلنَّارِۖ﴾ أي: كانوا يدعون الناس إلى الكفر الموجب للنار. ابن جزي:٢/١٤٣.\nكيف يكون الإنسان داعية إلى النار؟\nوَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ ٤١\nأي: جعلناهم زعماء يُتَّبعون على الكفر، فيكون عليهم وزرهم ووزر من اتبعهم؛ حتى يكون عقابهم أكثر. وقيل: جعل الله الملأ من قومه رؤساء السِّفلة منهم، فهم يدعون إلى جهنم. وقيل: أئمة يأتم بهم ذوو العبر، ويتعظ بهم أهل البصائر. القرطبي:١٦/٣٣٠.\nبيّن كيف كانوا زعماء في الكفر.\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُمۡ يَتَذَكَّرُونَ ٤٣\nإن الله -سبحانه وتعالى- كانت سنته قبل إنزال التوراة إذا كُذِّب نبي من الأنبياء ينتقم الله من أعدائه بعذاب من عنده؛ كما أهلك قوم نوح بالغرق، وقوم هود بالريح الصرصر، وقوم صالح بالصيحة، وقوم شعيب بالظلة، وقوم لوط بالحاصب، وقوم فرعون بالغرق. ابن تيمية:٥/٨٠.\nاذكر خمسة من أنواع عذاب الله للأمم العاصية.\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ\nوهذا دليل على أنه بعد نزول التوراة انقطع الهلاك العام، وشرع جهاد الكفار بالسيف. السعدي:٦١٧.\nهل حصل هلاكٌ عامٌّ لأمة من الأمم بعد هلاك فرعون وقومه؟"],[391,"§القصص\nwords\nالغَربِيِّالجَبَلِ الغَربِيِّ مِن مُوسَى -عليه السلام-.\nقَضَينَاعَهِدنَا.\nأَنشَأنَاخَلَقنَا.\nفَتَطَاوَلَ عَلَيهِمُ العُمُرُفَمَكَثُوا زَمَنًا طَوِيلًا.\nثَاوِيًامُقِيمًا.\ndeeds\nاختر واحدة من قصص القرآن واقرأ تفسيرها من كتب التفسير أو التاريخ؛ ففيها العظات والعبر.\nحدد عملًا تحس أنك قدمت هوى نفسك فيه على شرع الله ثم استغفر الله وقدم شرع الله على هوى نفسك.\nاستعذ بالله من اتباع الهوى، ومن الضلالة بعد الهدى.\nguid\nالإيمان والعلم لا بُدَّ لهما من التعاهد والمذاكرة؛ فإن تطاول العمر، ومرور الزمان يسببان النسيان.\nالمسلم يصدر عن الدليل الشرعي الصحيح.\nاعلم أنه لا يوجد كتاب أهدى من كتاب الله.\nrefl\nوَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِيِّ إِذۡ قَضَيۡنَآ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ ٤٤\n﴿وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِيِّ﴾: خطاب لسيدنا محمد -صلى الله عليه وسلم-؛ والمراد به إقامة حجة لإخباره بحال موسى وهو لم يحضره. و(الغربي): المكان الذي في غربي الطور؛ وهو المكان الذي كلم الله فيه موسى. والأمر المقضي إلى موسى هو النبوة. و﴿مِّنَ ٱلشَّٰهِدِينَ﴾ معناه: من الحاضرين هناك... المعنى: لم تحضر يا محمد للاطلاع على هذه الغيوب التي تخبر بها، ولكنها صارت إليك بوحينا؛ فكان الواجب على الناس المسارعة إلى الإيمان بك. ابن جزي:٢/١٤٥.\nكيف كان في خبر موسى -عليه السلام- دليل على أن هذا الكتاب من عند الله، وأن محمدًا رسول الله؟\nوَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ ٤٥\nفاندرس العلم، ونُسِيَت آياته؛ فبعثناك في وقت اشتدت الحاجة إليك، وإلى ما علمناك وأوحينا إليك. السعدي:٦١٧.\nمتى تتأكد الحاجة في الناس إلى وجود داعية يذكرهم ويعلمهم؟\nوَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ ٤٥\nوذلك أن الله تعالى قد عهد إلى موسى وقومه عهودًا في محمد -صلى الله عليه وسلم- والإيمان به، فلما طال عليهم العمر، وخُلِّفت القرون بعد القرون نسوا تلك العهود وتركوا الوفاء بها. البغوي:٣/٤٤٣.\nما الذي نسيه قوم موسى بتطاول العمر عليهم؟\nوَلَوۡلَآ أَن تُصِيبَهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ\nأي بما اقترفوا من الكفر والمعاصي. ويعبر عن كل الأعمال وإن لم تصدر عن الأيدي باجتراح الأيدي، وتقديم الأيدي لما أن أكثر الأعمال تزاول بها. الألوسي:١٠/٢٩٧.\nالأيدي نعمة من الله ووسيلة تستخدمها في الخير وفي الشر؛ وضح ذلك.\nفَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥٠\nدليل على أن كل من لم يستجب للرسول، وذهب إلى قول مخالف لقول الرسول؛ فإنه لم يذهب إلى هُدىً، وإنَّما ذهب إلى هوىً. السعدي:٦١٨.\nما علامة اتباع الهوى المذكورة في هذه الآية؟\nفَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥٠\nوالأهواء هي إرادات النفس بغير علم؛ فكل من فعل ما تريده نفسه بغير علم يبين أنه مصلحة؛ فهو متبع هواه. والعلم بالذي هو مصلحة العبد عند الله في الآخرة هو العلم الذي جاءت به الرسل. ابن تيمة:٥/٨٣.\nما المقصود بالأهواء التي يتبعها أهل الباطل؟\nوَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥٠\nواتباع الهوى -مع إلغاء إعمال النظر ومراجعته في النجاة- يلقي بصاحبه إلى كثير من أحوال الضرّ بدون تحديد ولا انحصار. ابن عاشور:٢٠/١٤١.\nما وجه كون متبع الهوى لا أضل منه؟"],[392,"§القصص\nwords\nوَصَّلنَافَصَّلنَا وَبَيَّنَّا.\nمَرَّتَينِلِإِيمَانِهِم بِكِتَابِهِم وَبِالقُرآنِ.\nوَيَدرَأُونَيَدفَعُونَ.\nنُتَخَطَّفنُنتَزَع بِسُرعَةٍ بِالقَتلِ، وَالأَسرِ.\nبَطِرَت مَعِيشَتَهَاطَغَت وَتَمَرَّدَت فِي حَيَاتِهَا.\ndeeds\nأنفق جزءًا من مالك في سبيل الله.\nاحضر مجلسًا من مجالس الذكر، وأقبل عليه بعقلك وسمعك.\nأرسل رسالة تحذر فيها من الإسراف والبطر في المعيشة؛ فهمًا من أسباب زوال النعمة، واستشهد بهذه الآية.\nguid\nبيان فضل أهل الكتاب إذا آمنوا بالنبي الأمي وكتابه، وأسلموا لله رب العالمين.\nفضيلة من يدرأ بالحسنة السيئة، وينفق مما رزقه الله.\nاجعل عباراتك خاليةً من الكلام البذيء والمؤذي، حتى مع العصاة.\nrefl\n۞وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ٥١\nوللتوصيل أحوال كثيرة: فهو باعتبار ألفاظه وصل بعضه ببعض ولم ينزل جملة واحدة، وباعتبار معانيه وصل أصنافًا من الكلام: وعدًا، ووعيدًا، وترغيبًا، وترهيبًا، وقصصًا ومواعظ وعبرًا، ونصائح يعقب بعضها بعضًا وينتقل من فن إلى فن؛ وفي كل ذلك عون على نشاط الذهن للتذكر والتدبر. ابن عاشور: ٢٠/١٤٢.\nبيّن أحوال توصيل القرآن الكريم.\nوَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ\nقيل: يدفعون بالاحتمال والكلام الحسن الأذى، وقيل: يدفعون بالتوبة والاستغفار الذنوب، وعلى الأول فهو وصف لمكارم الأخلاق؛ أي: من قال لهم سوءًا... قابلوه من القول الحسن بما يدفعه. القرطبي: ١٦/٢٩٦.\nكيف يكون درء السيئة بالحسنة؟\nوَإِذَا سَمِعُواْ ٱللَّغۡوَ أَعۡرَضُواْ عَنۡهُ وَقَالُواْ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ سَلَٰمٌ عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ ٥٥\nما أفصح عنه قولهم ﴿لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ﴾ من أن ذلك خلقهم: أنهم يتطلبون العلم، ومكارم الأخلاق. ابن عاشور: ٢٠/١٤٦.\nإلى ماذا يشير قول من آمن بالقرآن من أهل الكتاب: ﴿لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ﴾؟\nسَلَٰمٌ عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ ٥٥\n﴿سَلَٰمٌ عَلَيۡكُمۡۖ﴾ معناه هنا: المتاركة والمباعدة لا التحية، أو كأنه سلام الانصراف والبعد. ﴿لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ﴾ أي: لا نطلبهم للجدال والمراجعة في الكلام. ابن جزي:٢/١٤٧.\nما الذي ينبغي على المسلم فعله حين يكون في مجلس لغو وباطل؟\nإِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ٥٦\nفيقولون إن الاهتداء الذي في القلب لا يقدر عليه إلا الله، ولكن العبد يقدر على أسبابه، وهو المطلوب منه بقوله تعالى: ﴿ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ﴾، وهو المنفي عن الرسول -صلى الله عليه وسلم- بقوله: ﴿إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ﴾. ابن تيمية: ٥/٨٧.\nبيّن المقصود بالهداية التي لا يملكها إلا الله -سبحانه وتعالى-.\nوَقَالُوٓاْ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَآۚ أَوَ لَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنٗا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٖ رِّزۡقٗا مِّن لَّدُنَّا وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٥٧\nلا وجه لخوف من التخطف إن آمنوا؛ فإنهم لا يخافون منه وهم عبدة أصنام، فكيف يخافون إذا آمنوا وضموا حرمة الإيمان إلى حرمة المقام؟! الألوسي: ١٠/٣٠٥.\nفي الهداية والتزام شرع الله الأمان الحقيقي، وضح ذلك.\nوَكَمۡ أَهۡلَكۡنَا مِن قَرۡيَةِۢ بَطِرَتۡ مَعِيشَتَهَاۖ فَتِلۡكَ مَسَٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِيلٗاۖ وَكُنَّا نَحۡنُ ٱلۡوَٰرِثِينَ ٥٨\nومعنى بطرهم لها: أنهم شقوها بمجاوزة الحد في المرح، والأشر والفرح، إلى أن تعدوها فأفسدوها، وكفروها فلم يشكروها، بل فعلوا في تلقيها فعل الحائر المدهوش، فلم يحسنوا رعايتها. البقاعي: ١٤/٣٢٧.\nمتى يكون العيش ذو الرخاء الواسع سببًا للهلاك؟"],[393,"§القصص\nwords\nأَغوَينَادَعَونَاهُم لِلغَوَايَةِ فَاتَّبَعُونَا.\nفَعَمِيَتفَخَفِيَت.\nالخِيَرَةُالاِختِيَارُ.\ndeeds\nاستغفر الله تعالى وتب إليه هذا اليوم سبعين مرة.\nحدد أمرًا أنت مقبل عليه من أمور دنياك، ثم صل ركعتين للاستخارة، وادعُ بهذا الدعاء: «اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم؛ فإنك تقدر ولا أقدر، وتعلم ولا أعلم، وأنت علام الغيوب. اللهم إن كنت تعلم أن هذا الأمر -هنا تسمي حاجتك- خير لي في ديني ومعاشي وعاقبة أمري -أو قل: عاجل أمري وآجله-؛ فاقدره لي، ويسره لي، ثم بارك لي فيه. اللهم وإن كنت تعلم أن هذا الأمر -هنا تسمي حاجتك- شر لي في ديني ومعاشي وعاقبة أمري -أو قل: عاجل أمري وآجله-؛ فاصرفه عني، واصرفني عنه، واقدُر لي الخير حيث كان، ثم ارضني به».\nسل الله تعالى أن يصلح علانيتك وسريرتك.\nguid\nلا يشغلك طعام ولا لباس ولا مسكن في الدنيا عن ما في الآخرة.\nبراءة رؤساء الضلالة من أتباعهم يوم القيامة.\nإذا جاءك الدليل الصحيح فامتثله، واعمل به، وتذكر أن الله تعالى سيسألك ماذا أجبت الرسول.\nrefl\nوَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ ٦٠\n(فمتاع الحياة الدنيا وزينتها): فهو شيء شأنه أن يتمتع به، ويتزين به أيامًا قلائل. ويشعر بالقلة لفظ المتاع، وكذا ذكر أَبقى في المقابل. وفي لفظ الدنيا إشارة إلى القلة والخسة. ﴿وَمَا عِندَ ٱللَّهِ﴾ في الجنة؛ وهو الثواب، (خير) في نفسه من ذلك؛ لأنه لذة خالصة وبهجة كاملة. (وأبقى) لأنه أبدي، وأين المتناهي من غير المتناهي. ﴿أَفَلَا تَعۡقِلُونَ﴾ أي: ألا تتفكرون فلا تفعلون هذا الأمر الواضح، فتستبدلون الذي هو أدنى بالذي هو خير. الألوسي:١٠/٣٠٦.\nأشارت هذه الآية إلى حقارة الدنيا في مقابل الآخرة، وضح ذلك.\nوَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ ٦٠\nفدل ذلك أنه بحسب عقل العبد يؤثر الأخرى على الدنيا، وأنه ما آثر أحدٌ الدنيا إلا لنقص في عقله. السعدي:٦٢١.\nكيف تعرف العاقل من غير العاقل؟\nوَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ ٦٠\nوما عند الله لأهل طاعته وولايته خير مما أوتيتموه أنتم في هذه الدنيا من متاعها وزينتها. الطبري:١٩/٦٠٤.\nلماذا كانت أكثر عطايا الدنيا لأهل الكفر؟\nقَالَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغۡوَيۡنَآ أَغۡوَيۡنَٰهُمۡ كَمَا غَوَيۡنَاۖ تَبَرَّأۡنَآ إِلَيۡكَۖ مَا كَانُوٓاْ إِيَّانَا يَعۡبُدُونَ ٦٣\n﴿رَبَّنَا هَٰٓؤُلَآءِ﴾: إشارة إلى الأتباع. ﴿ٱلَّذِينَ أَغۡوَيۡنَآ﴾ أي: أوقعنا الإغواء -وهو الإضلال- بهم بما زينا لهم من الأقوال التي أعاننا على قبولهم أنها منا، مع كونها ظاهرة العوار، واضحة العار، ما خولتنا فيه في الدنيا من الجاه والمال. ثم استأنفوا ما يظنون أنه يدفع عنهم، فقالوا: (أغويناهم) أي: فغووا باختيارهم. البقاعي:١٤/٣٣٤.\nمن خلال الآية: بين خطورة الصحبة الفاسدة، والطاعة العمياء لهم.\nوَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ مَاذَآ أَجَبۡتُمُ ٱلۡمُرۡسَلِينَ ٦٥ فَعَمِيَتۡ عَلَيۡهِمُ ٱلۡأَنۢبَآءُ يَوۡمَئِذٖ فَهُمۡ لَا يَتَسَآءَلُونَ ٦٦\nيقول: فخفيت عليهم الأخبار؛ من قولهم: قد عمي عني خبر القوم: إذا خفي. وإنَّما عني بذلك أنهم عميت عليهم الحجة، فلم يدروا ما يحتجون؛ لأن الله تعالى قد كان أبلغ إليهم في المعذرة، وتابع عليهم الحجة، فلم تكن لهم حجة يحتجون بها، ولا خبر يخبرون به، مما تكون لهم به نجاة ومخلص. الطبري:١٩/٦٠٧.\nلماذا لا يجد العصاة حجة يحتجون بها يوم القيامة ؟\nفَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلۡمُفۡلِحِينَ ٦٧\nوعسى من الله موجبة؛ فإن هذا واقع بفضل الله ومنته لا محالة. ابن كثير:٣/٣٨٣.\nماذا تفيد كلمة (فعسى) إذا كانت من الله تعالى؟\nوَرَبُّكَ يَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ\nقال بعض العلماء: \"لا ينبغي لأحد أن يقدم على أمر من أمور الدنيا حتى يسأل الله الخيرة في ذلك؛ بأن يصلي ركعتين صلاة الاستخارة\". القرطبي:١٦/٣٠٨.\nكيف تتحصل على الخيرة من الله -سبحانه وتعالى- في أمور دنياك؟"],[394,"§القصص\nwords\nسَرمَدًادَائِمًا بَاقِيًا.\nوَضَلَّذَهَبَ.\nيَفتَرُونَيَختَلِقُونَهُ مِنَ الكَذِبِ.\nلَتَنُوءُ بِالعُصبَةِلَيَثقُلُ حَملُهَا عَلَى الجَمَاعَةِ الكَثِيرَةِ.\nوَابتَغِالتَمِس وَاطلُب.\nوَلاَ تَنسَ نَصِيبَكَلاَ تَترُك حَظَّكَ.\ndeeds\nتذكر نجاحًا حققته ثم اشكر الله سبحانه وتواضع له.\nحاول الليلة أن تنام مبكرًا وتصحو مبكرًا؛ فهذا من شكر نعمة الله وأقرب للفطرة.\nضع جدولًا لدخلك الشهري توازن فيه بين مصالحك في الدنيا والآخرة.\nguid\nالسماع الحقيقي هو: سماع القلب واستجابته.\nمِن شُكر الله تعالى: شَغلُ النهار بطلب العيش، والليل في السكون؛ وذلك فيما يرضي الله ولا يسخطه.\nمن لم يؤمن ويتيقن اليوم فسيعلم الحق إذا وقف بين يدي الله تعالى.\nrefl\nقُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ ٧١\nومن أبدع الاستدلال أن اختير للاستدلال على وحدانية الله هذا الصنع العجيب المتكرر كل يوم مرتين، والذي يستوي في إدراكه كل مميز، والذي هو أجلى مظاهر التغير في هذا العالم. ابن عاشور: ٢٠/١٦٨.\nلماذا اختير الاستدلال على وحدانية الله تعالى بتغير الليل والنهار؟\nقُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ ٧١\nفي هذه الآيات تنبيه إلى أن العبد ينبغي له أن يتدبر نِعَم الله عليه، ويتبصر فيها، ويقيسها بحال عدمها؛ فإنه إذا وازن بين حالة وجودها وبين حالة عدمها تنبه عقله لموضع المنة، بخلاف من جرى مع العوائد، ورأى أن هذا أمر لم يزل مستمرًا، ولا يزال، وعميَ قلبه عن الثناء على الله بنِعَمِهِ، ورؤية افتقاره إليها في كل وقت، فإن هذا لا يُحدِثُ له فكرُه شكرًا ولا ذكرًا. السعدي: ٦٢٣.\nتُنَبِّه الآيات إلى حالة من حالات التدبر والتفكر في نعمة الله؛ فما هي؟\nوَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ٧٣\nثم ذكر -عز وجل- انقسام الليل والنهار على السكون وابتغاء الفضل بالمشي والتصرف، وهذا هو الغالب في أمر الليل والنهار، فعدد النعمة بالأغلب، وإن وجد من يسكن بالنهار، ويبتغي فضل الله بالليل؛ فالشاذ النادر لا يعتد به. ابن عطية: ٤/٢٩٧.\nهل وجود من ينام بالنهار ويسهر بالليل يناقض معنى الآية؟ وضح ذلك.\nإِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ\nلما قال تعالى: (وما أوتيتم من شيء فمتاع الحياة الدنيا وزينتها) بيّن أن قارون أوتيها واغتر بها، ولم تعصمه من عذاب الله كما لم تعصم فرعون، ولستم أيها المشركون بأكثر عددًا ومالًا من قارون وفرعون؛ فلم ينفع فرعون جنوده وأمواله، ولم ينفع قارون قرابته من موسى ولا كنوزه. القرطبي: ١٦/٣١٢.\nبيّن لماذا ساق الله تعالى قصة قارون؟ وما العبرة من ذلك؟\nإِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ ٧٦\n﴿لَا تَفۡرَحۡۖ﴾: الفرح هنا هو الذي يقود إلى الإعجاب والطغيان، ولذلك قال: ﴿إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ﴾، وقيل: السرور بالدنيا؛ لأنه لا يفرح بها إلا من غفل عن الآخرة، ويدل على هذا قوله: ﴿وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡ﴾ [الحديد: ٢٣]. ابن جزي: ٢/١٥١.\nما الفرح المنهي عنه؟\nوَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ\nأي: لا تضيع حظك من دنياك، وتمتع بها؛ مع عملك للآخرة، وقيل: معناه لا تضيع عمرك بترك الأعمال الصالحات؛ فإن حظ الإنسان من الدنيا إنَّما هو بما يعمل فيها من الخير؛ فالكلام على هذا وعظ، وعلى الأول إباحة للتمتع بالدنيا لئلَّا ينفر عن قبول الموعظة. ﴿وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ﴾ أي: أحسن إلى عباد الله كما أحسن الله إليك بالغنى. ابن جزي: ٢/١٥١.\nكيف ينجو العبد من فتنة المال؟\nوَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ\nوإضافة النصيب إلى ضميره دالة على أنه حقه، وأن للمرء الانتفاع بماله فيما يلائمه في الدنيا؛ خاصة مما ليس من القربات، ولم يكن حرامًا. ابن عاشور: ٢٠/١٧٩\nلا ينبغي للمسلم أن يضيِّق على نفسه في مطعم أو مشرب وعنده سعة، بين ذلك."],[395,"§القصص\nwords\nالقُرُونِالأُمَمِ.\nوَلاَ يُسأَلُأَي: لاَ يُسأَلُونَ سُؤَالَ استِعلاَمٍ؛ بَل سُؤَالَ تَوبِيخٍ وَتَقرِيرٍ.\nوَيكَأَنَّكَلِمَةُ تَوَجُّعٍ، وَتَأَسُّفٍ، وَتَعَجُّبٍ.\nوَيكَأَنَّهُأَلَم تَعلَم أَنَّهُ؟\nعُلُوًّاتَكَبُّرًا.\ndeeds\nانصح من تعرف ممن يغترون بالمظاهر أن متاع الدنيا زائل، وذكّرهم بقصة قارون.\nاجلس مع عامل فقير، وتعرف إلى حاجته، وتصدق عليه.\nاستعذ بالله من العلو على الناس، والإفساد في الأرض.\nguid\nالفتنة أسرع إلى قلوب الماديين أبناء الدنيا.\nالفتنة إذا أقبلت لا يعلمها إلا العلماء، فإذا أدبرت عرفها كل الناس.\nفضل الله تعالى ورحمته أن ضاعف الحسنات، ولم يضاعف السيئات.\nrefl\nقَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَ لَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ\nألم يقف على ما يفيده العلم، ولم يعلم ما فعل الله تعالى بمن هو أشد منه قوة حسًّا أو معنىً، وأكثر مالًا أو جماعةً يحوطونه ويخدمونه؛ حتى لا يغتر بما اغتر به. الألوسي:١٠/٣٢٦.\nما سنة الله سبحانه فيمن اغتر بنفسه أو ماله؟\nوَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ\n﴿وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ﴾ أي: بأحوال الدنيا والآخرة كما ينبغي... وإنَّما لم يوصفوا بإرادة ثواب الآخرة تنبيهًا على أن العلم بأحوال النشأتين يقتضي الإعراض عن الأولى والإقبال على الأخرى حتمًا، وأن تمنِّي المتمنين ليس إلا لعدم علمهم بهما كما ينبغي. الألوسي:١٠/٣٢٧.\nمن أعرض عن زينة الدنيا عن علم، وأقبل على الآخرة عن علم؛ فإنه أثبت من غيره عند الفتن؛ وضّح ذلك من الآية.\nوَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ\nفليس ﴿ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ﴾ داعين بالويل على الذين يريدون الحياة الدنيا؛ لأن المناسب لمقام الموعظة لين الخطاب ليكون أعون على الاتعاظ، ولكنهم يتعجبون من تعلق نفوس أولئك بزينة الحياة الدنيا واغتباطهم بحال قارون دون اهتمام بثواب الله الذي يستطيعون تحصيله بالإقبال على العمل بالدين والعمل النافع، وهم يعلمون أن قارون غير متخلق بالفضائل الدينية. ابن عاشور:٢٠/١٨٤.\nماذا قصد أهل العلم بقولهم (ويلكم)؟\nوَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ ٨٠\n﴿إِلَّا ٱلصَّٰبِرُونَ﴾ يعني بذلك: الذين صبروا عن طلب زينة الحياة الدنيا، وآثروا ما عند الله -من جزيل ثوابه على صالحات الأعمال- على لذّات الدنيا وشهواتها؛ فجدّوا في طاعة الله، ورفضوا الحياة الدنيا. الطبري:١٩/٦٢٩.\nمن الذي يوفق للثبات في زمن الفتن؟\nوَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ ٨٠\n(وَلا يُلَقَّاهَا) أي: لا يجعل لاقيًا لهذا الكلمات أو النصيحة التي قالها أهل العلم؛ أي عاملًا بها ﴿إِلَّا ٱلصَّٰبِرُونَ﴾ أي: على قضاء ربهم في السراء والضراء، والحاملون أنفسهم على الطاعات، الذين صار الصبر لهم خلقًا. وعبر بالجمع ترغيبًا في التعاون إشارة إلى أن الدين لصعوبته لا يستقل به الواحد. البقاعي:١٤/٣٥٨.\nالصبر خلق عظيم يحتاج إلى تعاون، كيف دلت الآية على هذا المعنى؟\nفَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ\nجزاءٌ من جنس عمله؛ فكما رفع نفسه على عباد الله، أنزله الله أسفل سافلين، هو وما اغتر به من داره وأثاثه ومتاعه. السعدي:٦٢٤.\nلماذا عُذِّب قارون بعذاب الخسف دون أنواع العذاب الأخرى؟\nتِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ\nسورة القصص... افتتحها بأمر فرعون، وذكر علوه في الأرض؛ وهو الرياسة والشرف والسلطان، ثم ذكر في آخرها قارون وما أوتيه من الأموال، وذكر عاقبة سلطان هذا وعاقبة مال هذا، ثم قال: ﴿تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِي ٱلۡأَرۡضِ وَلَا فَسَادًاۚ﴾ كحال فرعون وقارون. ابن تيمية:٥/٩٠.\nلماذا ختمت سورة القصص بذكر صفتي أهل الجنة: أنهم لا يريدون علوًا في الأرض ولا فسادًا؟"],[396,"§القصص ، العنكبوت\nwords\nفَرَضَأَنزَلَ.\nلَرَآدُّكَ إِلَى مَعَادٍلَمُرجِعُكَ إِلَى المَوضِعِ الَّذِي خَرَجتَ مِنَهُ، وَهُوَ مَكَّةُ.\nتَرجُوتُؤَمِّلُ.\nيُلقَىيُنَزَّلَ.\nظَهِيرًاعَونًا.\nأَن يَسبِقُونَايُعجِزُونَا، وَيَفُوتُونَا بِأَنفُسِهِم.\ndeeds\nادعُ إلى الله -سبحانه وتعالى- بأي طريقة جائزة تحسنها.\nادع الله تعالى بقولك: \"اللهم يا مقلب القلوب ثبت قلبي على دينك\"؛ فإن النبي -صلى الله عليه وسلم- كان يكثر منه.\nاقرأ أخبار أحد الصحابة الذين تعرضوا للفتنة؛ كسلمان الفارسي، أو عمار بن ياسر مثلًا، وكيف صدقوا وصبروا.\nguid\nخطر رفقاء السوء، وأنهم سبب في الصد عن سبيل الله.\nيجب على العبد الخوف من الشرك؛ فإن الله نهى نبيه -صلى الله عليه وسلم- عن دعاء غير الله، فغيرُه من باب أولى.\nعظَم منزلة المجاهدة، وأن فيها خلاص النفس ونجاتها.\nrefl\nوَلَا يَصُدُّنَّكَ عَنۡ ءَايَٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَيۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ٨٧\nيعني: أقوالهم وكذبهم وأذاهم، ولا تلتفت نحوهم، وامض لأمرك وشأنك. القرطبي:١٦/٣٣٠.\nكيف دلت الآية على الاستمرار في الدعوة رغم العقبات المثبطة؟\nأَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ ٢\nأَظَنَّ الناسُ أَن يُترَكُوا بغير اختبار ولا ابتلاء؟ ﴿أَن يَقُولُواْ﴾ أي: بأن يقولوا: ﴿ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ﴾: لا يبتلون في أموالهم وأنفسهم؛ كلا، لنختبرنهم ليتبين المخلص من المنافق، والصادق من الكاذب. البغوي:٣/٤٦١.\nلماذا يبتلي الله تعالى عباده؟\nأَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ ٢\nنزلت في قوم من المؤمنين كانوا بمكة مستضعفين، وكان كفار قريش يؤذونهم، ويعذبونهم على الإسلام، فضاقت صدورهم بذلك؛ فآنسهم الله بهذه الآية، ووعظهم وأخبرهم أن ذلك اختبار ليوطنوا أنفسهم على الصبر على الأذى، والثبوت على الإيمان؛ فأعلمهم الله تعالى أن تلك سيرته في عباده: يسلط الكفار على المؤمنين ليمحصهم بذلك، ويظهر الصادق في إيمانه من الكاذب. ولفظها مع ذلك عام؛ فحكمها على العموم في كل من أصابته فتنة من معصية أو مضرة في النفس، والمال، وغير ذلك. ابن جزي:٢/١٥٤.\nمن خلال هذه الآية: بيّن فوائد الابتلاء.\nوَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ ٣\nوالمراد بالذين من قبلهم: المؤمنون أتباع الأنبياء -عليهم الصلاة والسلام- أصابهم من ضروب الفتن والمحن ما أصابهم فصبروا، وعضوا على دينهم بالنواجذ؛ كما يعرب عنه قوله تعالى: ﴿وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْ﴾ [آل عمران: ١٤٦]. الألوسي:١٠/٣٤٠.\nمن سنن الله تعالى ابتلاء المؤمنين، ما الواجب على المؤمن في هذه الحال؟\nوَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ ٣\nوالله عالم بهم قبل الاختبار، ومعنى الآية: وليظهرنّ الله الصادقين من الكاذبين؛ حتى يوجد معلومه الذي في أزله. البغوي:٣/٤٦٢.\nلقد علمت أن الله تعالى يعلم كل شيء، فما وجه قوله هنا: ﴿فَلَيَعۡلَمَنَّ ٱللَّهُ﴾؟\nأَمۡ حَسِبَ ٱلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسۡبِقُونَاۚ\nأي: أحسب الذين همهم فعل السيئات وارتكاب الجنايات أن أعمالهم ستُهمل، وأن الله سيغفل عنهم، أو يفوتونه؛ فلذلك أقدموا عليها، وسهل عليهم عملها. السعدي:٦٢٦.\nما الذي يسهل على العبد ارتكاب المعاصي والجنايات؟\nمَن كَانَ يَرۡجُواْ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَأٓتٖۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ٥\nمعنى الآية: من كان يرجو ثواب الله فليصبر في الدنيا على المجاهدة في طاعة الله حتى يلقى الله فيجازيه؛ فإن لقاء الله قريب الإتيان. ابن جزي:٢/١٥٥.\nما شرط الحصول على ثواب الله سبحانه؟"],[397,"§العنكبوت\nwords\nفِتنَةَ النَّاسِعَذَابَ النَّاسِ لَهُ، وَأَذَاهُم.\nسَبِيلَنَادِينَنَا.\nأَثقَالَهُمأَوزَارَهُم.\nيَفتَرُونَيَختَلِقُونَ مِنَ الكَذِبِ.\ndeeds\nأحسن إلى والديك بشراء هدية لهما.\nاقرأ كتابًا في فقه الفتن.\nانصح زميلك ألا يرسل رسالة محرمة عبر الهاتف الجوال؛ فإن عليه إثم كل من تأثر بها أو نشرها.\nguid\nوجوب بر الوالدين في المعروف، وعدم طاعتهما فيما هو منكر؛ كالشرك، والمعاصي.\nإذا ابتليت بمعصية فاحذر من دعوة غيرك إليها؛ خشية أن ينالك وزر من شاركك فيها.\nالاقتـداء بالأنبيـاء -عليهـم السلام- فـي صبرهم ومـا بذلوه للدعـوة.\nrefl\nوَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَئَِّاتِهِمۡ وَلَنَجۡزِيَنَّهُمۡ أَحۡسَنَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ ٧\nأي بأحسن أعمالهم؛ وهو الطاعة، وقيل: نعطيهم أكثر مما عملوا وأحسن. البغوي:٣/٤٦٣.\nكيف يجازى المؤمنون عند الله تعالى بأحسن ما عملوا؟\nوَإِن جَٰهَدَاكَ لِتُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَآۚ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ٨ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُدۡخِلَنَّهُمۡ فِي ٱلصَّٰلِحِينَ ٩\nومن لطيف مناسبة هذا الظرف في هذا المقام أن المؤمن لمَّا أمر بعصيان والديه إذا أمراه بالشرك كان ذلك مما يثير بينه وبين أبويه جفاء وتفرقة، فجعل الله جزاءً عن وحشة تلك التفرقة أُنسًا بجعله في عداد الصالحين؛ يأنس بهم. ابن عاشور:٢٠/٢١٥.\nأكرم الله تعالى من يقدم طاعته على طاعة الخلق غاية الإكرام، بين ذلك.\nوَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِيَ فِي ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ\nأي: جعل أذى الناس وعذابهم كعذاب الله في الآخرة؛ أي: جزع من أذى الناس، ولم يصبر عليه، فأطاع الناس كما يطيع الله من خاف من عذابه. البغوي:٣/٤٦٤.\nكيف يجعل المنافق فتنة الناس كعذاب الله تعالى؟\nوَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡۖ\nإخبار عن الدعاة إلى الكفر والضلالة؛ أنهم يحملون يوم القيامة أوزار أنفسهم، وأوزارًا بسبب ما أضلوا الناس، من غير أن ينقص من أوزار أولئك شيئًا. ابن كثير٦/٢٢٦.\nهل وزر الداعي للفساد نفس وزر المدعو المستجيب؟ وضّح هذا من خلال الآية.\nوَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡۖ\nفالذنب الذي فعله التابع لكلٍّ من التابع والمتبوع حصته منه؛ هذا لأنه فعله وباشره، والمتبوع لأنه تسبب في فعله ودعا إليه، كما أن الحسنة إذا فعلها التابع له أجرها بالمباشرة، وللداعي أجره بالتسبب. السعدي:٦٢٧.\nفي الآية حثٌّ من وجهٍ خَفِيٍّ على الدعوة إلى الله -سبحانه وتعالى- بَيِّن هذا الوجه.\nوَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ ١٤\nوالنكتة في اختيار السنة: أولًا أنها تطلق على الشدة والجدب بخلاف العام؛ فناسب اختيار السنة لزمان الدعوة الذي قاسى -عليه السلام- فيه ما قاسى من قومه. الألوسي:١٠/٣٤٨.\nما فوائد التعبير بسنة في قوله: ﴿أَلۡفَ سَنَةٍ﴾؟\nوَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ ١٤\nفأنت يا محمد، لا تأسف على من كفر بك من قومك، ولا تحزن عليهم؛ فإن الله يهدي من يشاء، ويضل من يشاء، وبيده الأمر، وإليه ترجع الأمور. ابن كثير:٣/٣٩٣.\nهل الهداية بمجرد العقل أم بماذا؟"],[398,"§العنكبوت\nwords\nوَتَخلُقُونَ إِفكًاتَفتَرُونَ كَذِبًا.\nفَابتَغُواالتَمِسُوا وَاطلُبُوا.\nبَدَأَ الخَلقَأَنشَأَهُ.\nتُقلَبُونَتُرَدُّونَ، وَتُرجَعُونَ.\nبِمُعجِزِينَفَائِتِينَ مِن عَذَابِهِ بِالهَرَبِ وَغَيرِهِ.\ndeeds\nادع الله تعالى أن يرزقك، ثم اجتهد في فعل السبب.\nاقرأ بعض الأحاديث من كتاب: ﴿بَدَأَ ٱلۡخَلۡقَۚ﴾ من صحيح البخاري لتتأمل عظيم قدرة الله.\nشاهد فيلمًا وثائقيًّا، أو صورًا عن مراحل خلق الإنسان؛ لتتذكر أصل خلقتك.\nguid\nالله تعالى هو الذي يرفع الفقر، ويكتب الرزق، ومن عداه لا يملك ذلك؛ فلنَدْعُهُ مباشرة.\nتقرير عجز الإنسان التام، وأنه لا مهرب يملك الفرار إليه إلا بالإيمان والتقوى.\nاليأس من رحمة الله من أسباب العذاب والهلاك.\nrefl\nفَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ ١٥\nلأن من لم يشاهد بقايا سفينة نوح يشاهد السفن فيتذكر سفينة نوح، وكيف كان صنعها بوحي من الله لإنجاء نوح ومن شاء الله نجاته، ولأن الذين من أهل قريتها يُخبرون عنها، وتنقل أخبارهم فتصير متواترة. ابن عاشور:٢٠/٢٢٣.\nكيف كانت سفينة نوح آية للعالمين؟\nإِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَٰنٗا وَتَخۡلُقُونَ إِفۡكًاۚ\nقال: (أ وثانًا) إشارة إلى تفرق الهم بكثرة المعبود، والكثرة يلزمها الفرقة، ولا خير في الفرقة. البقاعي:١٤/٤٠٧.\nما الذي أفاده جمع الأوثان في الآية؟\nفَٱبۡتَغُواْ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُواْ لَهُۥٓۖ إِلَيۡهِ تُرۡجَعُونَ ١٧\n(فابتغوا) وأشار بصيغة الافتعال إلى السعي فيه؛ لأنه أجرى عادته سبحانه أنه -في الغالب- لا يؤتيه إلا بكد من المرزوق وجهد: إما في العبادة والتوكل، وإما في السعي الظاهر في تحصيله بأسبابه الدنيوية، «والعاجز من أتبع نفسه هواها، وتمنى على الله الأماني». البقاعي:١٤/٤١٢- ٤١٣.\nكيف أشارت الآية إلى أن الرزق لا بد له من بذل السبب؟\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشۡأَةَ ٱلۡأٓخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٢٠\n﴿فَٱنظُرُواْ كَيۡفَ بَدَأَ ٱلۡخَلۡقَۚ﴾: على كثرتهم وتفاوت هيئاتهم، واختلاف ألسنتهم وألوانهم وطبائعهم، وانظروا إلى مساكن القرون الماضية وديارهم وآثارهم، كيف أهلكهم؛ لتعلموا بذلك كمال قدرة الله. القرطبي:١٧/٣٥٢.\nاذكر ثلاثة من آثار قدرة الله -سبحانه وتعالى-.\nيُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ ٢١\nأي: ترجعون إلى الدار التي بها تجري عليكم أحكام عذابه ورحمته، فاكتسبوا في هذه الدار ما هو من أسباب رحمته من الطاعات، وابتعدوا من أسباب عذابه وهي المعاصي. السعدي:٦٢٩.\nما الذي يستفيده المسلم من إخبار الله -سبحانه وتعالى- بأن الانقلاب إليه؟\nيُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ ٢١\nوابتُدئ بذكر العقاب؛ لأن الخطاب جار مع منكري البعث الذين حظهم فيه هو التعذيب. ابن عاشور:٢٠/٢٣٢.\nلماذا ابتدئ بذكر العذاب في الآية؟\nوَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُوْلَٰٓئِكَ يَئِسُواْ مِن رَّحۡمَتِي وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ ٢٣\nيحتمل أن يكون يأسهم في الآخرة، أو يكون وصف لحالهم في الدنيا؛ لأن الكافر يائس من رحمة الله، والمؤمن راج خائف. ابن جزي:٢/١٥٧.\nما الفرق بين المؤمن والكافر في نظرتهم إلى رحمة الله؟"],[399,"§العنكبوت\nwords\nمَوَدَّةَ بَينِكُمتَتَحَابُّونَ عَلَى عِبَادَتِهَا، وتَتَوَادُّونَ عَلَى خِدمَتِهَا.\nيَكفُرُيَتَبَرَّأُ.\nوَمَأوَاكُمُمَصِيرُكُم.\nمُهَاجِرٌتَارِكٌ دَارَ قَومِي إِلَى أَرضِ الشَّامِ المُبَارَكَةِ.\nأَجرَهُ فِي الدُّنيَابِالذِّكرِ الحَسَنِ، وَالوَلَدِ الصَّالِحِ وَالنُّبُوَّةِ فِي ذُرِّيَّتِهِ.\nنَادِيكُمُمَجلِسِكُمُ الَّذِي تَجتَمِعُونَ فِيهِ.\ndeeds\nقل: \"حسبي الله ونعم الوكيل\"؛ فهي مخرج من الشدائد؛ فقد قالها إبراهيم -عليه السلام- حين ألقي في النار.\nاهجر معصية من المعاصي التي تعرفها من نفسك، أو جليسًا يأمرك بسوء؛ فهي من الهجرة إلى الله.\nأنكر منكرًا رأيته بالموعظة والإقناع العقلي.\nguid\nالمؤمن واثق من دفاع الله ونصرته لمن ينصر دينه.\nالظلمة إذا أعيتهم الحجج يلجأون إلى استعمال القوة.\nمن ترك شيئًا لله عوضه الله خيرًا منه في الدنيا والآخرة.\nrefl\nفَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ\nوذلك لأنهم قام عليهم البرهان، وتوجهت عليهم الحجة، فعدلوا إلى استعمال جاههم وقوة ملكهم. ابن كثير ٣/٣٩٥.\nعلى ماذا يدل لجوء الظلمة إلى استخدام القوة؟\nفَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٢٤\nولم يجعل آية واحدة؛ لأنه آية لكل من شهده من قومه، ولأنه يدل على قدرة الله، وكرامة رسوله، وتصديق وعده، وإهانة عدوه، وأن المخلوقات كلها -جليلها وحقيرها- مسخرة لقدرة الله تعالى. ابن عاشور:٢٠/٢٣٥.\nيُعد إنجاء الله تعالى لإبراهيم -عليه السلام- من النار آيات لا آية واحدة، بين ذلك.\nوَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنٗا مَّوَدَّةَ بَيۡنِكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا\nويدخل في هذا كل من وافق أصحابه -من أهل المعاصي أو البطالة- على الرذائل؛ لِيَعُدُّوه حَسَنَ العشرة مُهَذَّبَ الأخلاق لطيفَ الذات، أو خوفًا من أن يصفوه بكثافة الطبع وسوء الصحبة. ولقد عم هذا -لعمري- أهل الزمان؛ ليوصفوا بموافاة الإخوان ومصافاة الخلان، معرضين عن رضى الملك الديان. البقاعي:١٤/٤٢٤.\nإرضاء الأصحاب والجلساء له حدود، وضح ذلك من الآية.\nوَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنٗا مَّوَدَّةَ بَيۡنِكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا\nعن قتادة، قال: \"صارت كل خلة في الدنيا عداوة على أهلها يوم القيامة إلا خلة المتقين\". الطبري:٢٠/٢٥.\nوضح فائدة الصحبة الخيّرة وعاقبة الصحبة السيئة.\nثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا\nتتبرأ الأوثان من عابديها، وتتبرأ القادة من الأتباع، ويلعن الأتباع القادة. البغوي:٣/٤٦٧.\nإذا كانت التبعيّة في الدنيا على معصية الله فما نتيجتها يوم القيامة؟\n۞فَـَٔامَنَ لَهُۥ لُوطٞۘ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٢٦\nلم يذكر الله عنهم أنه أهلكهم بعذاب، بل ذكر اعتزاله إياهم، وهجرته من بين أظهرهم... فلو كان الله استأصلهم بالعذاب لذكره كما ذكر إهلاك الأمم المكذبة، ولكن لعل من أسرار ذلك أن الخليل -عليه السلام- من أرحم الخلق وأفضلهم وأحلمهم وأجلهم، فلم يدعُ على قومه كما دعا غيره... ومما يدل على ذلك: أنه راجع الملائكة في إهلاك قوم لوط، وجادلهم، ودافع عنهم، وهم ليسوا قومه، والله أعلم بالحال. السعدي:٦٢٩-٦٣٠.\nمن صفات أولياء الله سبحانه أنهم أرحم الخلق بالخلق، وضح ذلك من خلال قصة إبراهيم -عليه السلام-.\nوَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ٢٨\nإن كثيرًا من المفاسد تكون الناس في غفلة عن ارتكابها لعدم الاعتياد بها، حتى إذا أقدم أحد على فعلها، وشوهد ذلك منه، تنبهت الأذهان إليها وتعلقت الشهوات بها. ابن عاشور:٢٠/٢٤١.\nبيّن خطورة السنة السيئة للمعاصي."]])